/* Developer workspace inside the monthly report; no navigation to /dev. */
(function(){
  'use strict';
  const trigger=document.getElementById('airDeveloperOpen');
  if(!trigger) return;
  const dialog=document.createElement('dialog');
  dialog.className='air-developer';
  dialog.id='airDeveloper';
  dialog.setAttribute('aria-labelledby','airDeveloperTitle');
  dialog.innerHTML='<header class="air-developer-head"><div><strong id="airDeveloperTitle">开发者模式</strong><span>数据链路 · 源表直查 · 接口调试</span></div><button type="button" class="air-developer-close" aria-label="关闭开发者模式">关闭 <span aria-hidden="true">×</span></button></header><div class="air-developer-status" role="status"><span></span><button type="button" hidden>重试</button></div><iframe title="AiOps 开发者工作台" hidden></iframe>';
  document.body.appendChild(dialog);
  const frame=dialog.querySelector('iframe'), status=dialog.querySelector('[role=status]');
  const retry=status.querySelector('button');
  let loaded=false, loading=false;
  function fit(){
    if(!dialog.open) return;
    const v=window.visualViewport;
    const width=v?v.width:window.innerWidth, height=v?v.height:window.innerHeight;
    const gap=Math.min(width<=600?6:12,width/8,height/8);
    Object.assign(dialog.style,{inset:'auto',margin:'0',left:((v?v.offsetLeft:0)+gap)+'px',top:((v?v.offsetTop:0)+gap)+'px',width:Math.max(1,width-gap*2)+'px',height:Math.max(1,height-gap*2)+'px'});
  }
  window.addEventListener('resize',fit);
  if(window.visualViewport){
    window.visualViewport.addEventListener('resize',fit);
    window.visualViewport.addEventListener('scroll',fit);
  }
  function close(){ dialog.close(); }
  dialog.querySelector('.air-developer-close').onclick=close;
  dialog.addEventListener('close',()=>{
    trigger.setAttribute('aria-expanded','false');
  });

  function hasWorkspace(source){
    if(typeof source!=='string' || !source) return false;
    const doc=new DOMParser().parseFromString(source,'text/html');
    return Boolean(doc.getElementById('apiBase') && doc.getElementById('menuSearch'));
  }

  function embeddedDocument(source){
    const doc=new DOMParser().parseFromString(source,'text/html');
    if(!doc.getElementById('apiBase') || !doc.getElementById('menuSearch')) throw new Error('服务器未返回开发者工作台，请确认已安装完整的新版本应用包');
    // The embedded workspace uses the report's application prefix, including a hosted access token.
    const base=doc.createElement('base');
    base.href=new URL('./',document.baseURI).href;
    doc.querySelectorAll('base').forEach(node=>node.remove());
    doc.head.prepend(base);
    // Use the one assistant in the parent report rather than starting another ADC session in srcdoc.
    doc.querySelectorAll('script').forEach(script=>{
      if(script.textContent.includes('ADCChat v1.4 一体版 F12 脚本')
          || script.textContent.includes('window.DC_SITE=')
          || /(?:shared\/dragon-claw\.js|\/\_\_platform\/adc\/client\.js)(?:\?|$)/.test(script.getAttribute('src')||'')) script.remove();
    });
    doc.querySelectorAll('#aiBar,#aiBarRz,#aiBarFab').forEach(node=>node.remove());
    const bootstrap=doc.createElement('script');
    bootstrap.textContent=`(()=>{
      if(parent.Icons&&!window.Icons)window.Icons=parent.Icons;
      const notify=action=>parent.postMessage({type:'aiops-developer',action},'*');
      window.__openAiBar=()=>notify('assistant');
      document.addEventListener('click',event=>{
        if(event.target.closest('a.topbar-ai[href="./"]')){event.preventDefault();notify('close');}
      });
      document.addEventListener('keydown',event=>{
        if(event.key==='Escape'&&!event.defaultPrevented&&!document.querySelector('.dlg-mask:not([hidden])')){event.preventDefault();notify('close');}
      });
    })();`;
    base.after(bootstrap);
    return '<!doctype html>\n'+doc.documentElement.outerHTML;
  }

  async function fetchWorkspaceSource(){
    const candidates=['dev.html','static/dev.html','api/dev-workspace'];
    for(const candidate of candidates){
      try{
        const response=await fetch(new URL(candidate,document.baseURI),{cache:'no-store'});
        if(!response.ok) continue;
        if(candidate.endsWith('dev-workspace')){
          const body=await response.json().catch(()=>null);
          if(hasWorkspace(body?.data?.html)) return body.data.html;
        }else{
          const text=await response.text();
          if(hasWorkspace(text)) return text;
        }
      }catch(_e){}
    }
    if(hasWorkspace(FALLBACK_WORKSPACE)) return FALLBACK_WORKSPACE;
    throw new Error('服务器未返回开发者工作台，请确认已安装完整的新版本应用包');
  }

  async function load(){
    if(loaded || loading) return;
    loading=true; status.hidden=false; retry.hidden=true;
    status.querySelector('span').textContent='正在加载开发者工作台…';
    try{
      const source=await fetchWorkspaceSource();
      const html=embeddedDocument(source);
      if(!dialog.open){ loading=false; return; }
      frame.hidden=false;
      // Give the developer sidebar its real viewport during initialization.
      frame.getBoundingClientRect();
      frame.addEventListener('load',()=>{
        loaded=true; loading=false; status.hidden=true; frame.hidden=false;
      },{once:true});
      frame.srcdoc=html;
    }catch(error){
      loading=false; status.querySelector('span').textContent=error.message||'开发者工作台加载失败'; retry.hidden=false;
    }
  }
  retry.onclick=load;
  trigger.onclick=()=>{
    if(!dialog.open) dialog.showModal();
    fit();
    trigger.setAttribute('aria-expanded','true');
    load();
  };
  window.addEventListener('message',event=>{
    if(event.source!==frame.contentWindow || !dialog.open || event.data?.type!=='aiops-developer') return;
    if(event.data.action==='close') close();
    if(event.data.action==='assistant'){
      close(); window.DragonClaw?.open();
    }
  });

  const FALLBACK_WORKSPACE = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>AiOps-Report · 运营数据工作台</title>\n  <style>\n    :root{\n      /* 背景层次 */\n      --bg-page:#f5f6fa; --bg-panel:#ffffff; --bg-subtle:#f1f4fb; --bg-soft:#f8fafc;\n      --bg-hover:rgba(99,102,241,0.06); --bg-selected:rgba(99,102,241,0.10);\n      --bg-user-card:#eef2ff; --bg-role-tag:#e0e7ff;\n      /* 文字 */\n      --text-primary:#0f172a; --text-heading:#1e293b;\n      --text-secondary:#475569; --text-muted:#94a3b8;\n      --text-on-brand:#4338ca;\n      /* 品牌色 */\n      --brand-50:#eef2ff; --brand-100:#e0e7ff; --brand-300:#a5b4fc;\n      --brand-500:#6366f1; --brand-600:#4f46e5; --brand-700:#4338ca;\n      --grad:linear-gradient(135deg,#6366f1 0%,#8b5cf6 100%);\n      --grad-soft:linear-gradient(135deg,rgba(99,102,241,0.12),rgba(139,92,246,0.12));\n      /* 边框 */\n      --border:#e2e8f0; --border-soft:#eef2f7; --border-strong:#cbd5e1;\n      /* 阴影 */\n      --shadow-xs:0 1px 2px rgba(15,23,42,0.04);\n      --shadow-sm:0 1px 3px rgba(15,23,42,0.05),0 1px 2px rgba(15,23,42,0.03);\n      --shadow-md:0 4px 12px rgba(15,23,42,0.06),0 2px 4px rgba(15,23,42,0.04);\n      --shadow-lg:0 12px 32px rgba(15,23,42,0.08),0 4px 8px rgba(15,23,42,0.04);\n      --shadow-pop:0 16px 48px rgba(15,23,42,0.12),0 4px 12px rgba(15,23,42,0.06);\n      /* 字体 */\n      --font:\"HMSymbol\",\"HarmonyOS Sans SC\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",\"PingFang SC\",Arial,sans-serif;\n      --mono:\"JetBrains Mono\",\"SFMono-Regular\",Consolas,\"Liberation Mono\",Menlo,monospace;\n      /* 圆角 */\n      --r-xs:4px; --r-sm:6px; --r-md:8px; --r-lg:12px; --r-xl:16px; --r-pill:999px;\n      --t-fast:0.15s ease; --t:0.2s ease;\n      /* 语义色 */\n      --c-read:#10b981; --c-write:#f59e0b; --c-biz:#3b82f6; --c-health:#8b5cf6; --c-local:#64748b;\n      --c-danger:#ef4444;\n    }\n    *{box-sizing:border-box}\n    html,body{margin:0;padding:0}\n    body{min-height:100vh;display:flex;flex-direction:column;background:var(--bg-page);font-family:var(--font);color:var(--text-primary);-webkit-font-smoothing:antialiased;font-size:14px;line-height:1.55}\n    button{font:inherit;color:inherit;background:none;border:none;padding:0;cursor:pointer}\n    input,select,textarea{font-family:inherit}\n    [hidden]{display:none!important}\n    /* 滚动条美化 */\n    ::-webkit-scrollbar{width:8px;height:8px}\n    ::-webkit-scrollbar-track{background:transparent}\n    ::-webkit-scrollbar-thumb{background:var(--border-strong);border-radius:var(--r-pill);border:2px solid transparent;background-clip:padding-box}\n    ::-webkit-scrollbar-thumb:hover{background:var(--text-muted);background-clip:padding-box}\n\n    /* ============ 顶栏 ============ */\n    .topbar{position:sticky;top:0;z-index:30;display:flex;align-items:center;gap:16px;padding:0 20px;height:60px;background:var(--bg-panel);border-bottom:1px solid var(--border);box-shadow:var(--shadow-xs)}\n    .brand{display:flex;align-items:center;gap:12px;min-width:0;flex:0 0 auto}\n    .brand .logo{width:36px;height:36px;border-radius:10px;background:var(--grad);display:flex;align-items:center;justify-content:center;font-size:18px;color:#fff;box-shadow:0 4px 12px rgba(99,102,241,0.35);flex:0 0 auto}\n    .brand .t{font-size:15px;font-weight:700;color:var(--text-heading);line-height:1.2;letter-spacing:-0.01em}\n    .brand .s{font-size:11.5px;color:var(--text-muted);margin-top:1px}\n    .topbar-spacer{flex:1}\n    .basefield{display:flex;align-items:center;gap:8px;flex:0 0 360px}\n    .basefield label{font-size:11.5px;color:var(--text-secondary);white-space:nowrap;font-weight:500}\n    .basefield input{flex:1;min-width:0;padding:7px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:12px;color:var(--text-primary);background:var(--bg-soft);outline:none;transition:all var(--t-fast)}\n    .basefield input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .healthpill{display:flex;align-items:center;gap:8px;padding:6px 14px;border-radius:var(--r-pill);background:var(--bg-soft);border:1px solid var(--border);font-size:12px;color:var(--text-secondary);white-space:nowrap;flex:0 0 auto;transition:all var(--t-fast)}\n    .healthpill:hover{border-color:var(--border-strong)}\n    .dot{width:8px;height:8px;border-radius:50%;background:var(--text-muted);flex:0 0 auto}\n    .dot.ok{background:var(--c-read);box-shadow:0 0 0 3px rgba(16,185,129,.18)}\n    .dot.fail{background:var(--c-danger);box-shadow:0 0 0 3px rgba(239,68,68,.18)}\n    .dot.busy{background:#f59e0b;box-shadow:0 0 0 3px rgba(245,158,11,.18)}\n\n    /* ============ 按钮 ============ */\n    .btn{padding:8px 16px;border-radius:var(--r-md);font-size:13px;font-weight:500;transition:all var(--t-fast);white-space:nowrap;display:inline-flex;align-items:center;gap:6px}\n    .btn-ghost{background:var(--bg-panel);border:1px solid var(--border);color:var(--text-secondary)}\n    .btn-ghost:hover{background:var(--bg-subtle);border-color:var(--border-strong);color:var(--text-primary)}\n    .btn-primary{background:var(--grad);color:#fff;border:none;box-shadow:0 2px 8px rgba(99,102,241,0.3)}\n    .btn-primary:hover{filter:brightness(1.06);box-shadow:0 4px 14px rgba(99,102,241,0.4)}\n    .btn-primary:disabled{opacity:.5;cursor:not-allowed;box-shadow:none}\n    .btn-danger{background:#ef4444;color:#fff;border:none;box-shadow:0 2px 8px rgba(239,68,68,0.3)}\n    .btn-danger:hover{filter:brightness(1.06);box-shadow:0 4px 14px rgba(239,68,68,0.4)}\n\n    /* ============ 主题化弹窗（替代浏览器原生 alert/confirm/prompt） ============ */\n    .dlg-mask{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;background:rgba(15,23,42,0.35);backdrop-filter:blur(2px);opacity:0;transition:opacity .18s ease}\n    .dlg-mask.show{opacity:1}\n    .dlg{width:440px;max-width:calc(100vw - 48px);max-height:calc(100vh - 80px);overflow:auto;background:var(--bg-panel);border:1px solid var(--border);border-radius:14px;box-shadow:0 18px 60px rgba(15,23,42,0.22);transform:translateY(10px) scale(0.98);transition:transform .18s ease}\n    .dlg-mask.show .dlg{transform:none}\n    .dlg-h{display:flex;align-items:center;justify-content:space-between;padding:16px 20px 0}\n    .dlg-t{font-size:15px;font-weight:600;color:var(--text-primary)}\n    .dlg-x{width:26px;height:26px;border:none;background:none;border-radius:6px;color:var(--text-muted);font-size:16px;line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all var(--t-fast)}\n    .dlg-x:hover{background:var(--bg-hover);color:var(--text-primary)}\n    .dlg-b{padding:12px 20px 4px;font-size:13px;color:var(--text-secondary);line-height:1.7;white-space:pre-line;overflow-wrap:break-word}\n    .dlg-inp{display:block;width:100%;margin-top:10px;padding:9px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-size:13px;background:var(--bg-soft);outline:none;transition:all var(--t-fast);color:var(--text-primary)}\n    .dlg-inp:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .dlg-f{display:flex;justify-content:flex-end;gap:10px;padding:16px 20px 18px}\n\n    /* ============ 主布局 ============ */\n    .main{display:flex;flex:1 0 auto;gap:20px;padding:20px;align-items:flex-start}\n    .left{flex:0 0 316px;width:316px;position:sticky;top:80px;display:flex;flex-direction:column;gap:12px;background:var(--bg-panel);border:1px solid var(--border);border-radius:var(--r-lg);box-shadow:var(--shadow-sm);max-height:calc(100vh - 100px)}\n/* ==== 左侧栏：右缘拖拽调宽 / 拖窄自动收起为图标栏 ==== */\n.left-rz{position:absolute;top:0;right:-4px;width:7px;height:100%;cursor:col-resize;z-index:7}\n.left-rz::after{content:'';position:absolute;top:15%;bottom:15%;left:50%;width:3px;transform:translateX(-50%);border-radius:3px;background:transparent;transition:background var(--t-fast)}\n.left-rz:hover::after,.left-rz.drag::after{background:var(--brand-500)}\nbody.left-dragging{user-select:none;cursor:col-resize}\n.left.rail .left-search,.left.rail .left-list{display:none}\n.left-rail{display:none;flex-direction:column;align-items:center;gap:6px;padding:12px 6px;overflow-y:auto}\n.left.rail .left-rail{display:flex}\n.rail-it{width:40px;height:40px;display:flex;align-items:center;justify-content:center;font-size:18px;border:none;background:none;border-radius:var(--r-md);cursor:pointer;transition:background var(--t-fast)}\n.rail-it:hover{background:var(--bg-hover)}\n.rail-it.active{background:var(--bg-selected)}\n.rail-sep{width:24px;height:1px;background:var(--border);flex:0 0 auto}\n/* ==== 全局保存成功 toast ==== */\n#toastWrap{position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:200;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}\n.toast{background:#1e293b;color:#fff;padding:10px 20px;border-radius:999px;font-size:13px;box-shadow:0 8px 24px rgba(15,23,42,0.28);opacity:0;transform:translateY(-10px);transition:all .25s ease;max-width:72vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.toast.show{opacity:1;transform:none}\n/* ==== 源表直查：表快查 ID 徽标 ==== */\n.tid{display:inline-block;margin-right:6px;padding:1px 5px;border-radius:4px;background:var(--brand-50);color:var(--brand-700);font-family:var(--mono);font-size:11px;font-weight:600;vertical-align:1px}\n.left-toolbar{display:flex;align-items:center;gap:6px}\n.left-toolbar .swrap{flex:1 1 auto;min-width:0}\n.ltb-btn{flex:0 0 auto;width:30px;height:30px;display:flex;align-items:center;justify-content:center;border:1px solid var(--border);border-radius:var(--r-md);background:var(--bg-soft);color:var(--text-secondary);cursor:pointer;transition:all var(--t-fast)}\n.ltb-btn:hover{color:var(--brand-600);border-color:var(--brand-300);background:var(--brand-50)}\n    .left-search{padding:12px 12px 4px;flex:0 0 auto}\n    .left-search .swrap{position:relative}\n    .left-search .swrap .sicon{position:absolute;left:11px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:13px;pointer-events:none}\n    .left-search input{width:100%;padding:8px 12px 8px 32px;border:1px solid var(--border);border-radius:var(--r-md);font-size:13px;background:var(--bg-soft);outline:none;transition:all var(--t-fast);color:var(--text-primary)}\n    .left-search input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .left-list{flex:1 1 auto;overflow-y:auto;padding:0 4px 8px}\n\n    /* 分组 */\n    .grp{margin-top:4px}\n    .grp-h{display:flex;align-items:center;gap:8px;padding:8px 12px;font-size:12px;font-weight:600;color:var(--text-secondary);cursor:pointer;user-select:none;border-radius:var(--r-md);transition:background var(--t-fast);letter-spacing:0.01em;text-transform:none}\n    .grp-h:hover{background:var(--bg-subtle)}\n    .grp-h .gicon{font-size:14px;flex:0 0 auto}\n    .grp-h .gname{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n    .grp-h .cnt{font-size:10.5px;font-weight:500;color:var(--text-muted);background:var(--bg-subtle);padding:1px 7px;border-radius:var(--r-pill);flex:0 0 auto}\n    .grp-h .caret{transition:transform var(--t-fast);font-size:10px;color:var(--text-muted);flex:0 0 auto}\n    .grp.closed .caret{transform:rotate(-90deg)}\n    .grp.closed .grp-b{display:none}\n    .grp-b{padding:0 4px}\n    .ep{display:flex;align-items:center;gap:8px;padding:7px 10px;cursor:pointer;transition:all var(--t-fast);border-radius:var(--r-md);border-left:2px solid transparent;margin:1px 0}\n    .ep:hover{background:var(--bg-hover)}\n    .ep.active{background:var(--bg-selected);border-left-color:var(--brand-500)}\n    .ep.active .ep-path{color:var(--brand-700);font-weight:600}\n    .m{font-family:var(--mono);font-size:10px;font-weight:700;padding:2px 6px;border-radius:var(--r-xs);min-width:46px;text-align:center;flex:0 0 auto;letter-spacing:0.02em}\n    .m.GET{color:#059669;background:rgba(16,185,129,.12)}\n    .m.POST{color:#2563eb;background:rgba(59,130,246,.12)}\n    .m.PUT{color:#d97706;background:rgba(245,158,11,.12)}\n    .m.DELETE{color:#dc2626;background:rgba(239,68,68,.12)}\n    .m.★{color:#7c3aed;background:rgba(124,112,243,.14)}\n    .ep-path{font-family:var(--mono);font-size:11.5px;color:var(--text-primary);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}\n    .ep-name{display:none}\n    .tag{font-size:10px;padding:2px 7px;border-radius:var(--r-pill);flex:0 0 auto;white-space:nowrap;font-weight:500}\n    .tag.read{color:var(--c-read);background:rgba(16,185,129,.1)}\n    .tag.write{color:var(--c-write);background:rgba(245,158,11,.1)}\n    .tag.biz{color:var(--c-biz);background:rgba(59,130,246,.1)}\n    .tag.health{color:var(--c-health);background:rgba(139,92,246,.1)}\n    .tag.local{color:var(--c-local);background:rgba(100,116,139,.12)}\n\n    /* ============ 右侧内容 ============ */\n    .right{flex:1 1 0;min-width:0;display:flex;flex-direction:column;gap:16px}\n    .card{background:var(--bg-panel);border:1px solid var(--border);border-radius:var(--r-lg);box-shadow:var(--shadow-sm);padding:18px 20px}\n    .card-h{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700;color:var(--text-heading);margin-bottom:14px;flex-wrap:wrap;letter-spacing:-0.01em}\n    .card-h .hicon{width:24px;height:24px;border-radius:6px;background:var(--grad-soft);display:flex;align-items:center;justify-content:center;font-size:13px;flex:0 0 auto}\n    .card-h .desc{font-size:12px;font-weight:400;color:var(--text-muted);margin-left:2px}\n    .reqrow{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}\n    .reqrow select{padding:8px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;background:var(--bg-panel);color:var(--text-primary);outline:none;transition:all var(--t-fast);cursor:pointer}\n    .reqrow select:focus{border-color:var(--brand-500);box-shadow:0 0 0 3px var(--brand-50)}\n    .reqrow input.pathin{flex:1;min-width:200px;padding:8px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;background:var(--bg-soft);outline:none;transition:all var(--t-fast)}\n    .reqrow input.pathin:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .params{display:flex;gap:12px;margin-bottom:14px;flex-wrap:wrap}\n    .params label{font-size:12px;color:var(--text-secondary);display:flex;flex-direction:column;gap:5px;font-weight:500}\n    .params label span{font-family:var(--mono);font-size:11px;color:var(--brand-600)}\n    .params input{padding:7px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;width:160px;outline:none;background:var(--bg-soft);transition:all var(--t-fast)}\n    .params input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .bodywrap{margin-bottom:14px}\n    .bodywrap .bl{font-size:12px;color:var(--text-secondary);margin-bottom:7px;display:flex;align-items:center;gap:8px;font-weight:500}\n    .bodywrap .bl button{font-size:11px;color:var(--brand-700);background:var(--brand-50);padding:3px 10px;border-radius:var(--r-pill);transition:all var(--t-fast);font-weight:500}\n    .bodywrap .bl button:hover{background:var(--brand-100)}\n    textarea.body{width:100%;min-height:128px;resize:vertical;padding:12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:12.5px;line-height:1.6;background:var(--bg-soft);color:var(--text-primary);outline:none;tab-size:2;transition:all var(--t-fast)}\n    textarea.body:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n    .toolbar .n{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-secondary)}\n    .toolbar .n input{width:64px;padding:7px 10px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;text-align:center;outline:none;background:var(--bg-soft);transition:all var(--t-fast)}\n    .toolbar .n input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .spacer{flex:1}\n    /* ============ 快捷测试数据按钮组（仅写入类端点显示） ============ */\n    .qtests{margin-bottom:14px;border:1px dashed var(--border-strong);border-radius:var(--r-md);padding:10px 12px;background:var(--bg-soft)}\n    .qtests .qt-h{font-size:12px;color:var(--text-secondary);margin-bottom:8px;display:flex;align-items:center;gap:6px;font-weight:500;flex-wrap:wrap}\n    .qtests .qt-h .qt-tip{font-weight:400;color:var(--text-muted);font-size:11px}\n    .qtests .qt-h .qt-auto{margin-left:auto;display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-muted);font-weight:400;cursor:pointer;user-select:none}\n    .qtests .qt-h .qt-auto input{margin:0;cursor:pointer}\n    .qtests .qt-list{display:flex;flex-wrap:wrap;gap:6px}\n    .qtests .qt-btn{padding:5px 11px;border-radius:var(--r-pill);font-size:11.5px;font-weight:500;border:1px solid var(--border);background:var(--bg-panel);color:var(--text-secondary);transition:all var(--t-fast);white-space:nowrap}\n    .qtests .qt-btn:hover{border-color:var(--brand-300);background:var(--brand-50);color:var(--brand-700)}\n    .qtests .qt-btn:active{transform:scale(.96)}\n    .qtests .qt-btn.qt-edge{border-color:rgba(245,158,11,.4);background:rgba(245,158,11,.06);color:#b45309}\n    .qtests .qt-btn.qt-edge:hover{border-color:var(--c-write);background:rgba(245,158,11,.14)}\n    .qtests .qt-btn.qt-del{border-color:rgba(239,68,68,.35);background:rgba(239,68,68,.05);color:#b91c1c}\n    .qtests .qt-btn.qt-del:hover{border-color:var(--c-danger);background:rgba(239,68,68,.12)}\n\n    /* 响应速度 */\n    .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(108px,1fr));gap:10px;margin-bottom:4px}\n    .stat{background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:14px 12px;text-align:center;transition:all var(--t-fast)}\n    .stat:hover{border-color:var(--border)}\n    .stat .v{font-size:22px;font-weight:700;font-family:var(--mono);color:var(--text-heading);line-height:1.1;letter-spacing:-0.02em}\n    .stat .v small{font-size:12px;font-weight:400;color:var(--text-muted);margin-left:2px}\n    .stat .l{font-size:11px;color:var(--text-muted);margin-top:5px;font-weight:500}\n    .stat.fast .v{color:var(--c-read)} .stat.mid .v{color:var(--c-write)} .stat.slow .v{color:var(--c-danger)}\n    .stat.status .v{font-size:16px}\n    .stat.ok .v{color:var(--c-read)} .stat.err .v{color:var(--c-danger)}\n    .err-box{background:rgba(239,68,68,.05);border:1px solid rgba(239,68,68,.2);border-radius:var(--r-md);padding:12px 14px;color:#b91c1c;font-family:var(--mono);font-size:12.5px;white-space:pre-wrap;word-break:break-all;line-height:1.6}\n\n    /* 链路图（保留用于可能的展开查看） */\n    .flow{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding:6px 0}\n    .fnode{min-width:150px;max-width:220px;flex:1 1 0;border:1px solid var(--border);border-radius:var(--r-md);padding:10px 12px;background:var(--bg-soft);position:relative}\n    .fnode .fn-t{font-size:11px;font-weight:700;color:var(--brand-700);display:flex;align-items:center;gap:6px;margin-bottom:6px}\n    .fnode .fn-d{font-family:var(--mono);font-size:11px;color:var(--text-primary);line-height:1.45;word-break:break-all}\n    .fnode .fn-m{font-size:10px;color:var(--text-muted);margin-top:6px;line-height:1.4}\n    .fnode.hl-app{border-color:rgba(245,158,11,.5)}\n    .fnode.hl-biz{border-color:rgba(59,130,246,.5)}\n    .farrow{display:flex;align-items:center;justify-content:center;color:var(--brand-300);font-size:18px;padding:0 4px;flex:0 0 auto}\n    .farrow small{position:absolute}\n    .io{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}\n    .io .col{background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:10px 12px;min-width:0}\n    .io .col .h{font-size:11px;font-weight:700;color:var(--text-heading);margin-bottom:8px;display:flex;align-items:center;gap:6px}\n    .io .col ul{margin:0;padding:0;list-style:none;font-size:11.5px;color:var(--text-secondary);line-height:1.7}\n    .io .col li{display:flex;gap:6px;align-items:baseline}\n    .io .col li b{font-family:var(--mono);color:var(--text-primary);font-weight:600;flex:0 0 auto}\n    .io .col li span{color:var(--text-secondary)}\n    @media(max-width:768px){.io{grid-template-columns:1fr}}\n\n    /* JSON 高亮 */\n    .code{font-family:var(--mono);font-size:12.5px;line-height:1.6;background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:14px;overflow:auto;max-height:480px;white-space:pre;tab-size:2}\n    .j-k{color:#7c3aed} .j-s{color:#059669} .j-n{color:#d97706} .j-b{color:#2563eb} .j-null{color:var(--text-muted);font-style:italic}\n    .meta-line{font-size:11.5px;color:var(--text-muted);display:flex;gap:14px;flex-wrap:wrap;margin-bottom:10px;font-family:var(--mono);align-items:center}\n    .cache-badge{display:inline-flex;align-items:center;gap:6px;background:var(--brand-50);color:var(--brand-700);border-radius:var(--r-pill);padding:2px 10px;font-size:11px;font-weight:500}\n    .cache-re{font-size:11px;color:var(--brand-700);background:var(--brand-100);border-radius:var(--r-pill);padding:2px 8px;transition:all var(--t-fast);font-weight:500;border:none;cursor:pointer}\n    .cache-re:hover{background:var(--brand-300);color:#fff}\n    .empty{padding:80px 20px;text-align:center;color:var(--text-muted);font-size:14px}\n    .empty .big{font-size:56px;opacity:.25;margin-bottom:16px}\n    .empty .hint{margin-top:8px}\n    .foot{padding:10px 20px 24px;color:var(--text-muted);font-size:11px;text-align:center}\n    .hint{font-size:11.5px;color:var(--text-muted);margin-top:8px;line-height:1.6}\n\n    /* 源表直查 */\n    .srcbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px;align-items:center}\n    .srcbar input{flex:1;min-width:220px;padding:8px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;background:var(--bg-soft);outline:none;transition:all var(--t-fast)}\n    .srcbar input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .srcbar .cbx{flex:2;min-width:280px}\n    .srcbar select{padding:8px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;background:var(--bg-panel);outline:none;cursor:pointer;transition:all var(--t-fast)}\n    .srcbar select:focus{border-color:var(--brand-500);box-shadow:0 0 0 3px var(--brand-50)}\n    .fltr{display:flex;gap:6px;margin:2px 0 8px}\n    .fltr input{flex:1;min-width:0;padding:7px 10px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:12px;background:var(--bg-soft);outline:none;transition:all var(--t-fast)}\n    .fltr input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .fltr .fcolbox{flex:0 0 24%;min-width:110px}\n    .fltr .fop{flex:0 0 92px;padding:7px 8px;border:1px solid var(--border);border-radius:var(--r-md);font-size:12px;background:var(--bg-panel);cursor:pointer}\n    .fltr .fx{flex:0 0 28px;color:var(--text-muted);border:1px solid var(--border);border-radius:var(--r-md);background:var(--bg-panel);transition:all var(--t-fast)}\n    .fltr .fx:hover{color:var(--c-danger);border-color:rgba(239,68,68,.4);background:rgba(239,68,68,.05)}\n    .srcmeta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px}\n    .badge{font-size:11px;padding:3px 10px;border-radius:var(--r-pill);font-weight:500}\n    .badge.mod{color:var(--brand-700);background:var(--brand-50)}\n    .badge.src{color:#dc2626;background:rgba(239,68,68,.1)}\n    .badge.land{color:var(--c-biz);background:rgba(59,130,246,.1)}\n    .badge.time{color:var(--text-muted);background:var(--bg-subtle);font-family:var(--mono);font-weight:400}\n    .badge.biz{color:#7c3aed;background:rgba(124,112,243,.12)}\n    .audit-row{border:1px solid var(--border-soft);border-radius:var(--r-md);padding:8px 12px;margin-bottom:6px;background:var(--bg-panel);transition:all var(--t-fast)}\n    .audit-row:hover{border-color:var(--border)}\n    .audit-detail{border-top:1px dashed var(--border);margin-top:8px;padding-top:8px}\n    .audit-detail-inner{font-size:12px}\n    .mapline{font-size:12px;color:var(--text-secondary);line-height:1.9;margin-bottom:10px}\n    .mapline code{font-family:var(--mono);font-size:11.5px;background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-xs);padding:1px 6px;color:var(--text-primary)}\n    .mapline .arw{color:var(--brand-300);padding:0 6px}\n    .mapline b{color:var(--text-secondary);font-weight:600;font-size:11.5px}\n    /* 落地表切换器 */\n    .land-switcher{display:flex;gap:8px;align-items:center;background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:8px 12px;margin:0 0 10px}\n    .land-switcher .lbl{font-size:11.5px;color:var(--text-secondary);white-space:nowrap;font-weight:500}\n    .land-switcher .cbx{flex:1;min-width:200px}\n    /* 可搜索下拉 combobox */\n    .cbx{position:relative;flex:1;min-width:160px}\n    .cbx input{width:100%;padding:8px 30px 8px 12px;border:1px solid var(--border);border-radius:var(--r-md);font-family:var(--mono);font-size:13px;background:var(--bg-soft);outline:none;transition:all var(--t-fast);color:var(--text-primary)}\n    .cbx input:focus{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n    .cbx .carrow{position:absolute;right:12px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:10px;pointer-events:none;transition:transform var(--t-fast)}\n    .cbx.open .carrow{transform:translateY(-50%) rotate(180deg)}\n    .cbx .cl{position:absolute;top:calc(100% + 6px);left:0;right:0;max-height:300px;overflow-y:auto;background:var(--bg-panel);border:1px solid var(--border);border-radius:var(--r-md);box-shadow:var(--shadow-pop);z-index:50;padding:4px;display:none}\n    .cbx.open .cl{display:block}\n    .cbx .cl li{padding:7px 10px;border-radius:var(--r-sm);cursor:pointer;font-family:var(--mono);font-size:12px;color:var(--text-primary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.4;transition:background var(--t-fast)}\n    .cbx .cl li:hover{background:var(--bg-subtle)}\n    .cbx .cl li .cd{font-size:11px;color:var(--text-muted);margin-left:8px;overflow:hidden;text-overflow:ellipsis}\n    .cbx .cl li.act{background:var(--brand-50);color:var(--brand-700)}\n    .cbx .cl li.cur{background:var(--bg-subtle)}\n    .cbx .cl li.nm{color:var(--text-muted);cursor:default;font-size:11.5px;text-align:center;padding:10px}\n    /* 表名下拉彩色标签（模块/类别/空表） */\n    .cbx .cl li.dim{color:var(--text-muted)}\n    .cbx .cl li.dim .cd{color:var(--text-muted)}\n    .cbx .cl li .ctag{display:inline-block;font-size:10px;line-height:1;padding:2.5px 6px;margin-left:6px;border-radius:4px;vertical-align:1px;font-family:var(--font);white-space:nowrap;flex:none}\n    .ctag.tm{background:#eef2ff;color:#4f46e5}\n    .ctag.tg-pub{background:#dcfce7;color:#15803d}\n    .ctag.tg-maj{background:#fee2e2;color:#b91c1c}\n    .ctag.tg-risk{background:#ffedd5;color:#c2410c}\n    .ctag.tg-rect{background:#fef3c7;color:#b45309}\n    .ctag.tg-lie{background:#dbeafe;color:#1d4ed8}\n    .ctag.tg-acct{background:#ccfbf1;color:#0f766e}\n    .ctag.tg-maint{background:#cffafe;color:#0e7490}\n    .ctag.tg-inc{background:#fce7f3;color:#be185d}\n    .ctag.tg-sr{background:#ede9fe;color:#6d28d9}\n    .ctag.tg-task{background:#e0e7ff;color:#4338ca}\n    .ctag.tg-net{background:#e0f2fe;color:#0369a1}\n    .ctag.tg-chg{background:#fef9c3;color:#a16207}\n    .ctag.tg-ioc{background:#f1f5f9;color:#475569}\n    .ctag.tg-dlv{background:#ecfccb;color:#4d7c0f}\n    .ctag.tg-derv{background:#f3e8ff;color:#7e22ce}\n    .ctag.tg-oth{background:#e2e8f0;color:#334155}\n    .ctag.te{background:#f1f5f9;color:#94a3b8;border:1px dashed #cbd5e1}\n    .ctag.tg-hot{background:#fff7ed;color:#ea580c;font-weight:600}\n\n/* Dragon Claw 助理浮窗样式见 shared/dragon-claw.css */\n/* 多选列下拉（「只显示这些列」） */\n.msel .msel-box{display:flex;flex-wrap:wrap;align-items:center;gap:4px;min-height:34px;padding:4px 28px 4px 8px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--bg-soft);cursor:text;transition:all var(--t-fast)}\n.msel .msel-box:focus-within{border-color:var(--brand-500);background:#fff;box-shadow:0 0 0 3px var(--brand-50)}\n.msel .chip{display:inline-flex;align-items:center;gap:3px;max-width:170px;padding:2px 5px 2px 8px;background:var(--brand-50);border:1px solid var(--brand-100);border-radius:var(--r-xs);font-family:var(--mono);font-size:11px;color:var(--brand-700);overflow:hidden;white-space:nowrap}\n.msel .chip button{flex:0 0 auto;font-size:11px;color:var(--brand-500);line-height:1;padding:0 2px;transition:color var(--t-fast)}\n.msel .chip button:hover{color:var(--c-danger)}\n.msel .msel-box input{width:auto;flex:1 1 140px;min-width:120px;padding:3px 0;border:none;background:transparent;font-family:var(--mono);font-size:12px;color:var(--text-primary);box-shadow:none}\n.msel .msel-box input:focus{border:none;box-shadow:none}\n.msel .msel-list{position:absolute;top:calc(100% + 6px);left:0;right:0;background:var(--bg-panel);border:1px solid var(--border);border-radius:var(--r-md);box-shadow:var(--shadow-pop);z-index:50;display:none}\n.msel.open .msel-list{display:block}\n.msel .msel-bar{display:flex;align-items:center;gap:6px;padding:6px 10px;border-bottom:1px solid var(--border-soft);font-size:11.5px;color:var(--text-muted)}\n.msel .msel-bar .msel-cnt{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\n.msel .msel-bar button{flex:0 0 auto;padding:2px 9px;border:1px solid var(--border-soft);border-radius:var(--r-xs);background:var(--bg-soft);font-size:11.5px;color:var(--brand-600);transition:all var(--t-fast)}\n.msel .msel-bar button:hover{background:var(--brand-50);border-color:var(--brand-300);color:var(--brand-700)}\n.msel .msel-ll{list-style:none;margin:0;padding:4px;max-height:280px;overflow-y:auto}\n.msel .msel-ll.two{columns:2;column-gap:2px}\n.msel .msel-ll li{display:flex;align-items:center;gap:7px;padding:6px 8px;border-radius:var(--r-sm);cursor:pointer;font-family:var(--mono);font-size:12px;color:var(--text-primary);break-inside:avoid;transition:background var(--t-fast)}\n.msel .msel-ll li:hover{background:var(--bg-subtle)}\n.msel .msel-ll li .ck{width:14px;height:14px;flex:0 0 auto;border:1.5px solid var(--border-strong);border-radius:4px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:9px;color:transparent;transition:all var(--t-fast)}\n.msel .msel-ll li.on{color:var(--brand-700);font-weight:500;background:var(--brand-50)}\n.msel .msel-ll li.on .ck{background:var(--brand-500);border-color:var(--brand-500);color:#fff}\n.msel .msel-ll li.nm{color:var(--text-muted);cursor:default;font-size:11.5px;text-align:center;padding:12px}\n    .dtable-wrap{max-height:440px;overflow:auto;border:1px solid var(--border-soft);border-radius:var(--r-md);background:var(--bg-panel)}\n    .dtable{width:100%;border-collapse:collapse;font-size:12px;background:var(--bg-panel)}\n    .dtable th{position:sticky;top:0;background:var(--bg-subtle);text-align:left;font-size:11px;color:var(--text-secondary);font-weight:600;padding:8px 12px;border-bottom:1px solid var(--border);white-space:nowrap;z-index:1}\n    .dtable td{padding:7px 12px;border-bottom:1px solid var(--border-soft);font-family:var(--mono);font-size:11.5px;color:var(--text-primary);white-space:nowrap;max-width:340px;overflow:hidden;text-overflow:ellipsis}\n    .dtable tr:hover td{background:var(--bg-hover)}\n    .dtable tr:last-child td{border-bottom:none}\n\n    /* 响应输出格式切换 */\n    .fmt{display:flex;border:1px solid var(--border);border-radius:var(--r-md);overflow:hidden;margin-left:auto;background:var(--bg-soft)}\n    .fmt button{padding:6px 14px;font-size:12px;color:var(--text-secondary);background:var(--bg-panel);transition:all var(--t-fast);font-weight:500}\n    .fmt button:hover{background:var(--bg-subtle)}\n    .fmt button.active{background:var(--brand-500);color:#fff;font-weight:600}\n    .fmt button+button{border-left:1px solid var(--border)}\n\n    /* 层级树 */\n    .troot{font-family:var(--mono);font-size:12px;line-height:1.6;background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:12px 14px;overflow:auto;max-height:480px;tab-size:2}\n    .trow{white-space:nowrap}\n    .tparent{cursor:pointer;user-select:none;border-radius:var(--r-xs);padding:1px 0;transition:background var(--t-fast)}\n    .tparent:hover{background:var(--bg-hover)}\n    .tcaret{display:inline-block;width:14px;color:var(--text-muted)}\n    .tchild{margin-left:7px;padding-left:12px;border-left:1px dashed var(--border-strong)}\n    .t-k{color:#7c3aed;font-weight:600}\n    .t-typ{color:var(--text-muted);font-size:11px}\n    .t-typ.obj{color:var(--c-biz)}.t-typ.arr{color:var(--c-write)}\n    .t-s{color:#059669}\n    .t-n{color:#d97706}.t-b{color:#2563eb}.t-null{color:var(--text-muted);font-style:italic}\n\n    /* 数据链路说明卡片 */\n    .fnode.dim{opacity:.42}\n    .chain-txt{margin:6px 0 12px}\n    .chain-txt p{margin:0 0 10px;background:var(--bg-soft);border:1px solid var(--border-soft);border-radius:var(--r-md);padding:10px 14px;font-size:12.5px;line-height:1.75;color:var(--text-primary)}\n    .chain-txt p:last-child{margin-bottom:0}\n    .chain-txt b{color:var(--brand-700);font-weight:600}\n    .io .col .plain{font-family:var(--mono);font-size:11.5px;color:var(--text-secondary);line-height:1.6;word-break:break-all}\n    /* 链路卡片折叠 */\n    #chainCard .card-h{cursor:pointer;user-select:none;display:flex;align-items:center;gap:6px}\n    #chainCard .card-h .toggle-ic{margin-left:auto;font-size:12px;color:var(--text-muted);transition:transform .2s}\n    #chainCard.collapsed .toggle-ic{transform:rotate(-90deg)}\n    #chainCard .chain-summary{display:none;font-size:12.5px;color:var(--text-secondary);margin-top:6px;line-height:1.5}\n    #chainCard.collapsed .chain-summary{display:block}\n    #chainCard.collapsed .flow,\n    #chainCard.collapsed .chain-txt,\n    #chainCard.collapsed .io{display:none}\n    /* 过滤条件跨表校验 */\n    .warn{background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.35);border-radius:var(--r-md);padding:8px 12px;font-size:12px;color:#92400e;margin:0 0 10px;line-height:1.6}\n    .fltr.off{opacity:.5}\n    .fltr.off input{background:var(--bg-subtle)}\n    .fltr .fcolbox input.bad{border-color:rgba(245,158,11,.65)}\n\n    /* 页脚 */\n    .foot{font-size:9px;color:var(--text-muted);text-align:center;padding:4px 0 8px;letter-spacing:.02em}\n\n    /* 响应式 */\n    @media(max-width:1024px){\n      .left{flex:0 0 240px;width:240px}\n      .basefield{flex:1 1 240px}\n    }\n    @media(max-width:768px){\n      .main{flex-direction:column;padding:12px}\n      .left{flex:1 1 auto;width:auto;max-height:none}\n      .basefield{flex:1 1 100%}\n      .brand .s{display:none}\n    }\n\n    /* ============ 视觉刷新：与平台 Dragon Claw 统一（深海军蓝顶栏 + 青绿→靛蓝强调 + 线性图标） ============ */\n    :root{\n      --bg-page:#f3f6fb;\n      --brand-50:#eef2ff; --brand-100:#e0e7ff; --brand-300:#a5b4fc; --brand-400:#818cf8; --brand-500:#6366f1; --brand-600:#4f46e5; --brand-700:#4338ca;\n      --teal-500:#14b8a6; --teal-600:#0d9488;\n      --grad:linear-gradient(135deg,#0d9488 0%,#6366f1 100%);\n      --grad-soft:linear-gradient(135deg,rgba(20,184,166,.12),rgba(99,102,241,.12));\n      --shadow-sm:0 1px 2px rgba(15,23,42,.04),0 4px 12px rgba(15,23,42,.04);\n      --shadow-md:0 8px 24px rgba(15,23,42,.08),0 2px 6px rgba(15,23,42,.04);\n      --r-lg:14px;\n    }\n    body{background:radial-gradient(1200px 500px at 85% -10%,rgba(99,102,241,.08),transparent 60%),radial-gradient(900px 400px at -10% 10%,rgba(20,184,166,.07),transparent 60%),var(--bg-page);background-attachment:fixed}\n    ::selection{background:rgba(20,184,166,.22)}\n    [data-i] svg,.gicon svg,.hicon svg,.rail-it svg{display:block}\n    /* 顶栏 */\n    .topbar{height:62px;background:linear-gradient(90deg,#0b1220 0%,#111c33 55%,#131f3d 100%);border-bottom:1px solid rgba(148,163,184,.14);box-shadow:0 6px 24px rgba(2,6,23,.18);color:#e2e8f0}\n    .topbar::after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,rgba(100,255,218,.55),rgba(96,165,250,.55),transparent)}\n    .brand .logo{width:38px;height:38px;padding:0;overflow:hidden;background:none;border-radius:12px;box-shadow:0 0 0 1px rgba(100,255,218,.4),0 6px 18px rgba(20,184,166,.3)}\n    .brand .logo img{width:100%;height:100%;object-fit:cover;display:block}\n    .brand .t{color:#f8fafc;font-size:15.5px;display:flex;align-items:center;gap:8px}\n    .brand .t .ver{font-size:10px;font-weight:600;letter-spacing:.04em;padding:2px 7px;border-radius:999px;color:#04211c;background:linear-gradient(90deg,#5eead4,#93c5fd)}\n    .brand .s{color:#8b9ab3}\n    .basefield label{color:#8b9ab3}\n    .basefield input{background:rgba(15,23,42,.6);border-color:rgba(148,163,184,.22);color:#e2e8f0}\n    .basefield input:focus{background:rgba(15,23,42,.85);border-color:rgba(100,255,218,.55);box-shadow:0 0 0 3px rgba(100,255,218,.12)}\n    .healthpill{background:rgba(15,23,42,.6);border-color:rgba(148,163,184,.22);color:#cbd5e1}\n    .healthpill:hover{border-color:rgba(148,163,184,.4)}\n    .topbar-ai{display:inline-flex;align-items:center;gap:7px;padding:6px 12px 6px 6px;border-radius:999px;border:1px solid rgba(100,255,218,.35);background:rgba(20,184,166,.1);color:#ccfbf1;font-size:12px;font-weight:600;white-space:nowrap;transition:all var(--t)}\n    .topbar-ai img{width:24px;height:24px;border-radius:50%;object-fit:cover}\n    a.topbar-ai{text-decoration:none;padding:6px 12px}\n    .topbar-ai [data-i] svg{width:15px;height:15px}\n    .topbar-ai:hover{background:rgba(20,184,166,.2);border-color:rgba(100,255,218,.6);transform:translateY(-1px)}\n    /* 按钮 */\n    .btn{border-radius:9px;transition:all var(--t)}\n    .btn svg{width:14px;height:14px}\n    .btn-primary{background:var(--grad);box-shadow:0 4px 12px rgba(13,148,136,.25)}\n    .btn-primary:hover{filter:brightness(1.07);box-shadow:0 6px 18px rgba(79,70,229,.3);transform:translateY(-1px)}\n    .btn-primary:active,.btn-ghost:active{transform:translateY(0) scale(.98)}\n    .btn-ghost:hover{border-color:var(--brand-300);color:var(--brand-700);background:var(--brand-50)}\n    /* 左侧菜单 */\n    .left{border-color:rgba(226,232,240,.9);box-shadow:var(--shadow-sm)}\n    .left-search .swrap .sicon{display:flex;color:var(--text-muted)}\n    .left-search .swrap .sicon svg{width:14px;height:14px}\n    .grp-h .gicon{display:grid;place-items:center;width:24px;height:24px;border-radius:7px;color:var(--brand-600);background:var(--grad-soft)}\n    .grp-h .gicon svg{width:14px;height:14px}\n    .grp-h .caret{display:inline-block}\n    .ep{border-left:0;position:relative;padding-left:12px}\n    .ep::before{content:'';position:absolute;left:3px;top:8px;bottom:8px;width:3px;border-radius:3px;background:transparent;transition:background var(--t-fast)}\n    .ep:hover{background:rgba(20,184,166,.06)}\n    .ep.active{background:linear-gradient(90deg,rgba(20,184,166,.12),rgba(99,102,241,.08))}\n    .ep.active::before{background:var(--grad)}\n    .rail-it{color:var(--text-secondary)}\n    .rail-it svg{width:18px;height:18px}\n    .rail-it:hover{color:var(--brand-600)}\n    .rail-it.active{color:var(--brand-700);background:var(--grad-soft)}\n    /* 卡片 */\n    .card{border-color:rgba(226,232,240,.95);transition:box-shadow var(--t),border-color var(--t)}\n    .card:hover{box-shadow:var(--shadow-md)}\n    .card:not([hidden]){animation:cardIn .35s cubic-bezier(.2,.8,.2,1) both}\n    .right>.card:nth-child(2){animation-delay:.03s}.right>.card:nth-child(3){animation-delay:.06s}.right>.card:nth-child(4){animation-delay:.09s}\n    @keyframes cardIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n    .card-h{font-size:14.5px}\n    .card-h .hicon{width:28px;height:28px;border-radius:9px;color:#fff;background:var(--grad);box-shadow:0 4px 10px rgba(13,148,136,.22)}\n    .card-h .hicon svg{width:15px;height:15px}\n    .card-h .hicon img{width:100%;height:100%;border-radius:9px;object-fit:cover}\n    .qtests .qt-h [data-i]{display:inline-flex;color:var(--teal-600)}\n    .qtests .qt-h [data-i] svg{width:14px;height:14px}\n    .stat{border-radius:12px;background:linear-gradient(180deg,#fff,var(--bg-soft))}\n    .stat:hover{transform:translateY(-1px);box-shadow:var(--shadow-sm)}\n    .dtable th{background:#f1f5fb}\n    .dtable tr:hover td{background:rgba(20,184,166,.05)}\n    .fmt button.active{background:var(--grad)}\n    /* 空状态 */\n    .empty{padding:96px 20px}\n    .empty .big{display:grid;place-items:center;width:72px;height:72px;margin:0 auto 18px;border-radius:22px;opacity:1;color:#fff;background:var(--grad);box-shadow:0 14px 36px rgba(13,148,136,.25);animation:emptyFloat 4s ease-in-out infinite}\n    .empty .big svg{width:30px;height:30px}\n    @keyframes emptyFloat{50%{transform:translateY(-5px)}}\n    .empty .lead{font-size:15px;font-weight:600;color:var(--text-heading)}\n    /* AI 问答卡 */\n    .adc-feats{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin:0 0 14px}\n    .adc-feat{display:flex;gap:10px;padding:12px;border:1px solid var(--border-soft);border-radius:12px;background:var(--bg-soft)}\n    .adc-feat [data-i]{display:grid;place-items:center;flex:none;width:30px;height:30px;border-radius:9px;color:var(--teal-600);background:var(--grad-soft)}\n    .adc-feat b{display:block;font-size:12.5px;color:var(--text-heading);margin-bottom:2px}\n    .adc-feat span{font-size:11.5px;color:var(--text-secondary);line-height:1.55}\n    .foot{font-size:11px;padding:6px 0 14px}\n    @media(prefers-reduced-motion:reduce){.card:not([hidden]),.empty .big{animation:none}}\n    @media(max-width:768px){.topbar{gap:10px;padding:0 12px}.basefield{display:none}.healthpill{padding:6px 9px}.healthpill #hText{display:none}.topbar-ai span{display:none}.topbar-ai{padding:4px}.brand .t .ver{display:none}}\n  </style>\n  <link rel=\"stylesheet\" href=\"shared/dragon-claw.css\">\n</head>\n<body>\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <div class=\"logo\"><img src=\"data:image/jpeg;base64,\" alt=\"\"></div>\n      <div>\n        <div class=\"t\">AiOps-Report <span class=\"ver\">v1.4.4</span></div>\n        <div class=\"s\">运营数据工作台 · 数据链路 / 源表直查 / Dragon Claw 助理</div>\n      </div>\n    </div>\n    <div class=\"topbar-spacer\"></div>\n    <div class=\"basefield\">\n      <label>API 基地址</label>\n      <input id=\"apiBase\" spellcheck=\"false\">\n    </div>\n    <div class=\"healthpill\"><span class=\"dot\" id=\"hDot\"></span><span id=\"hText\">检测中…</span></div>\n    <a class=\"topbar-ai\" href=\"./\" title=\"返回 AI 月报\"><span data-i=\"file\"></span><span>AI 月报</span></a>\n    <button class=\"topbar-ai\" type=\"button\" onclick=\"window.__openAiBar&&window.__openAiBar()\" title=\"打开 Dragon Claw 助理\"><img src=\"data:image/jpeg;base64,\" alt=\"\"><span>Dragon Claw</span></button>\n  </header>\n\n  <div class=\"main\">\n    <!-- 左侧：搜索 + 端点列表 + 链路说明 -->\n    <aside class=\"left\">\n      <nav class=\"left-rail\" id=\"leftRail\" aria-label=\"分类快捷栏\"></nav>\n      <div class=\"left-rz\" id=\"leftRz\" title=\"拖拽调整宽度（拖窄自动收起为图标栏）\"></div>\n      <div class=\"left-search\">\n        <div class=\"left-toolbar\">\n          <div class=\"swrap\">\n            <span class=\"sicon\" data-i=\"search\"></span>\n            <input id=\"menuSearch\" placeholder=\"搜索接口（路径 / 名称 / 分组）\" spellcheck=\"false\" autocomplete=\"off\">\n          </div>\n          <button id=\"grpExpandAll\" type=\"button\" class=\"ltb-btn\" title=\"一键展开全部分组\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"7 13 12 18 17 13\"></polyline><polyline points=\"7 6 12 11 17 6\"></polyline></svg></button>\n          <button id=\"grpCollapseAll\" type=\"button\" class=\"ltb-btn\" title=\"一键折叠全部分组\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"17 11 12 6 7 11\"></polyline><polyline points=\"17 18 12 13 7 18\"></polyline></svg></button>\n        </div>\n      </div>\n      <div class=\"left-list\" id=\"leftPanel\"></div>\n    </aside>\n\n    <!-- 右侧 -->\n    <section class=\"right\" id=\"rightPanel\">\n      <div class=\"card collapsed\" id=\"chainCard\" hidden>\n        <div class=\"card-h\" id=\"chainToggle\"><span class=\"hicon\" data-i=\"compass\"></span>数据链路说明 <span class=\"desc\" id=\"chainEp\"></span><span class=\"toggle-ic\">▾</span></div>\n        <div class=\"chain-summary\" id=\"chainSummary\"></div>\n        <div class=\"flow\" id=\"chainFlow\"></div>\n        <div class=\"chain-txt\" id=\"chainTxt\"></div>\n        <div class=\"io\" id=\"chainIO\"></div>\n      </div>\n\n      <div class=\"card\" id=\"reqCard\" hidden>\n        <div class=\"card-h\" id=\"reqTitle\"></div>\n        <div class=\"reqrow\">\n          <select id=\"methodSel\"></select>\n          <input id=\"pathIn\" class=\"pathin\" spellcheck=\"false\">\n        </div>\n        <div class=\"params\" id=\"paramsWrap\" hidden></div>\n        <div class=\"bodywrap\" id=\"bodyWrap\" hidden>\n          <div class=\"bl\"><span>请求体 (JSON)</span><button id=\"fmtBody\">格式化</button></div>\n          <textarea class=\"body\" id=\"bodyIn\" spellcheck=\"false\"></textarea>\n        </div>\n        <div class=\"qtests\" id=\"quickTests\" hidden>\n          <div class=\"qt-h\">\n            <span data-i=\"flask\"></span><span>快捷测试数据</span><span class=\"qt-tip\">点一个按钮 → 填入请求体/参数 → 自动发送（橙色=边界/非法数据，红色=删除）</span>\n            <label class=\"qt-auto\"><input type=\"checkbox\" id=\"qtAutoSend\" checked>填充后自动发送</label>\n          </div>\n          <div class=\"qt-list\" id=\"qtList\"></div>\n        </div>\n        <div class=\"toolbar\">\n          <button class=\"btn btn-primary\" id=\"sendBtn\">发送请求</button>\n          <div class=\"n\"><span>压测次数</span><input id=\"loadN\" type=\"number\" min=\"1\" max=\"50\" value=\"5\"></div>\n          <button class=\"btn btn-ghost\" id=\"loadBtn\">压测</button>\n          <div class=\"spacer\"></div>\n          <button class=\"btn btn-ghost\" id=\"copyCurl\">复制 cURL</button>\n        </div>\n      </div>\n\n      <div class=\"card\" id=\"statCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\" data-i=\"zap\"></span>响应速度</div>\n        <div class=\"stats\" id=\"stats\"></div>\n        <div class=\"hint\">计时口径：从发起 fetch 到收到完整响应的总耗时（含后端调用基座 REST API 的往返）。压测为并发发起 N 次后统计。</div>\n      </div>\n\n      <div class=\"card\" id=\"srcCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\" data-i=\"table\"></span>源表直查 <span class=\"desc\">输上游源表名或业务库落地表名 → 自动映射并查数据（映射来自《运营指标-索引目录》）</span></div>\n        <div class=\"srcbar\">\n          <div class=\"cbx\" id=\"srcCb\"></div>\n          <select id=\"srcLimit\" title=\"返回行数（不限 = 自动分页取全部，上限 5 万行）\">\n            <option>10</option><option>20</option><option>50</option><option selected>100</option><option>500</option><option value=\"0\">不限</option>\n          </select>\n          <button class=\"btn btn-ghost\" id=\"srcAddFlt\" type=\"button\">＋ 过滤条件</button>\n          <button class=\"btn btn-primary\" id=\"srcBtn\">直查</button>\n          <button class=\"btn btn-ghost\" id=\"srcSaveBtn\" type=\"button\" title=\"把当前 表/行数/过滤条件/显示列/落地表 保存为自定义查询（左侧⭐菜单一键重查）\"><span data-i=\"save\"></span>保存为自定义</button>\n        </div>\n        <div id=\"srcFltWrap\"></div>\n        <div id=\"srcFltWarn\" class=\"warn\" hidden></div>\n        <div class=\"srcbar\" style=\"margin-top:2px\">\n          <div id=\"srcCols\" class=\"cbx\"></div>\n        </div>\n        <div class=\"hint\" style=\"margin:0 0 10px\">下拉已内置业务库 netcare 全量 441 张表：有数据的靠前，<b>空表置灰排在最后</b>（可查但无数据）；彩色标签 = 所属模块 / 数据类别，灰色备注 = 同事标注的中文名（可输入中文搜索）。\n        输索引目录里的源表名也能命中对应落地表，任意表名可直接输入回车。\n        「只显示这些列」点开为<b>多选</b>：列名搜索 / 全选 / 反选 / 清空，选择按表自动记忆到本地浏览器。\n        过滤条件可加多条（AND）：列名 + 运算符 + 值；运算符 = != &gt; &lt; &gt;= &lt;= like not like in（like 值可带 %，in 用逗号分隔多值）。查询成功后可在「本模块其他落地表」切换器中换表重查——\n        切换时会先用新表的真实字段校验过滤条件：新表没有的列对应的条件会自动置灰、不随查询下发（其他条件与列选择保留）。</div>\n        <div id=\"srcCustomTip\" class=\"hint\" style=\"margin:8px 0 0\" hidden></div>\n        <div id=\"srcResult\"></div>\n      </div>\n\n      <div class=\"card\" id=\"auditCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\" data-i=\"clipboard\"></span>全表盘点 <span class=\"desc\">项目内所有提到的表（源表/落地表/business_tables/数据元素绑定表）→ 逐表体检：中文备注 / 估算行数 / 前 20 行 / 粒度口径 / 归属核对</span></div>\n        <div class=\"srcbar\">\n          <span class=\"hint\" id=\"auditSummary\" style=\"margin:0\">加载中…</span>\n          <div class=\"spacer\"></div>\n          <button class=\"btn btn-primary\" id=\"auditRunAll\" type=\"button\"><span data-i=\"refresh\"></span>全部检查（并发3）</button>\n          <button class=\"btn btn-ghost\" id=\"auditStop\" type=\"button\" disabled>停止</button>\n        </div>\n        <div class=\"audit-filter\" style=\"margin:8px 0;display:flex;gap:10px;align-items:center;flex-wrap:wrap\">\n          <label style=\"font-size:12px;color:var(--text-secondary);display:flex;align-items:center;gap:5px;cursor:pointer\"><input type=\"checkbox\" id=\"auditFltSrc\" checked> 源表</label>\n          <label style=\"font-size:12px;color:var(--text-secondary);display:flex;align-items:center;gap:5px;cursor:pointer\"><input type=\"checkbox\" id=\"auditFltLand\" checked> 落地表</label>\n          <label style=\"font-size:12px;color:var(--text-secondary);display:flex;align-items:center;gap:5px;cursor:pointer\"><input type=\"checkbox\" id=\"auditFltBiz\" checked> business_tables</label>\n          <label style=\"font-size:12px;color:var(--text-secondary);display:flex;align-items:center;gap:5px;cursor:pointer\"><input type=\"checkbox\" id=\"auditFltElem\" checked> 数据元素绑定</label>\n          <input id=\"auditKw\" class=\"pathin\" style=\"flex:1;min-width:180px\" placeholder=\"关键字过滤表名（回车应用）\" spellcheck=\"false\">\n        </div>\n        <div id=\"auditProgress\" class=\"hint\" style=\"margin:4px 0\"></div>\n        <div id=\"auditList\"></div>\n      </div>\n\n      <div class=\"card\" id=\"respCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\" data-i=\"box\"></span>响应输出\n          <span class=\"fmt\" id=\"respFmt\">\n            <button type=\"button\" data-fmt=\"json\" class=\"active\">JSON</button>\n            <button type=\"button\" data-fmt=\"tree\">层级</button>\n            <button type=\"button\" data-fmt=\"table\">表格</button>\n          </span>\n        </div>\n        <div class=\"meta-line\" id=\"respMeta\"></div>\n        <div id=\"respBody\"></div>\n      </div>\n\n      <div class=\"card\" id=\"freeCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\" data-i=\"flask\"></span>自由请求 <span class=\"desc\">任意 method / path / body，用于临时探索</span></div>\n        <div class=\"reqrow\">\n          <select id=\"fMethod\">\n            <option>GET</option><option>POST</option><option>PUT</option><option>DELETE</option>\n          </select>\n          <input id=\"fPath\" class=\"pathin\" value=\"/healthz\" spellcheck=\"false\">\n        </div>\n        <div class=\"bodywrap\">\n          <div class=\"bl\"><span>请求体 (JSON，可选)</span></div>\n          <textarea class=\"body\" id=\"fBody\" style=\"min-height:70px\" spellcheck=\"false\"></textarea>\n        </div>\n        <div class=\"toolbar\">\n          <button class=\"btn btn-ghost\" id=\"fSend\">发送</button>\n          <span class=\"hint\" style=\"margin:0\">结果填充到上方「响应输出」</span>\n        </div>\n      </div>\n\n      <div class=\"card\" id=\"adcCard\" hidden>\n        <div class=\"card-h\"><span class=\"hicon\"><img src=\"data:image/jpeg;base64,\" alt=\"\"></span>Dragon Claw 助理 <span class=\"desc\">常驻右侧 · 对话查数 · 经确认后修改应用数据</span></div>\n        <div class=\"adc-feats\">\n          <div class=\"adc-feat\"><span data-i=\"search\"></span><div><b>自然语言查数</b><span>直接提问，Dragon Claw 自动查表结构、写只读 SQL、汇总结论并注明口径。</span></div></div>\n          <div class=\"adc-feat\"><span data-i=\"shield\"></span><div><b>写入先确认</b><span>新增 / 修改 / 删除应用表前展示变更预览，你点确认后才执行，并记录审计日志。</span></div></div>\n          <div class=\"adc-feat\"><span data-i=\"database\"></span><div><b>能力由后端开放</b><span>工具清单来自 /api/agent/capabilities，业务库只读、SQL 守卫在服务端强制。</span></div></div>\n        </div>\n        <div class=\"hint\" style=\"margin:0 0 12px\">首次提问会经浮窗内嵌的<b>原 ADC 聊天页</b>自动建立会话，之后直连对话接口；助理栏切换菜单不刷新，可拖动、调大小，Esc 收起。\n          <b>只有部署到数字人云端（与 ADC 同源）后才能真实对话</b>，本地仅预览界面。</div>\n        <div class=\"toolbar\">\n          <span class=\"hint\" id=\"adcStatus\">状态见右侧助理栏</span>\n          <div class=\"spacer\"></div>\n          <button class=\"btn btn-primary\" id=\"adcOpenBar\" type=\"button\"><span data-i=\"sparkles\"></span>打开 Dragon Claw</button>\n        </div>\n      </div>\n\n      <div class=\"empty\" id=\"emptyHint\">\n        <div class=\"big\" data-i=\"pointer\"></div>\n        <div class=\"lead\">从左侧选择一个接口开始</div>\n        <span class=\"hint\">每个接口标注了它走哪条数据链路：应用 Schema（读/写）· 业务库只读 · 健康检查</span>\n      </div>\n    </section>\n\n<!-- 右侧常驻 AI 助理（Dragon Claw）：菜单切换不刷新、可拖动、可调大小、可收起 -->\n    <div class=\"aibar-rz\" id=\"aiBarRz\" title=\"拖动调整宽度\"></div>\n    <aside class=\"aibar collapsed\" id=\"aiBar\" tabindex=\"-1\" aria-label=\"Dragon Claw 助理\">\n      <div class=\"aibar-h\">\n        <img class=\"aibar-avatar\" id=\"aiBarAvatar\" src=\"data:image/jpeg;base64,\" alt=\"\">\n        <div class=\"aibar-tt\">\n          <div class=\"aibar-title\">Dragon Claw <span class=\"aibar-badge\">ONLINE BETA</span></div>\n          <div class=\"aibar-sub\"><span class=\"aibar-live\" id=\"aiBarDot\"></span><span id=\"aiBarStatus\">未初始化</span></div>\n        </div>\n        <div class=\"spacer\"></div>\n        <button class=\"aibar-icon\" id=\"aiBarCapsBtn\" type=\"button\" title=\"可调用的数据能力\" aria-expanded=\"false\" data-i=\"database\"></button>\n        <button class=\"aibar-icon\" id=\"aiBarNewSess\" type=\"button\" disabled title=\"新建会话\" data-i=\"edit\"></button>\n        <button class=\"aibar-icon\" id=\"aiBarClose\" type=\"button\" title=\"最小化（Esc）\" data-i=\"minus\"></button>\n      </div>\n      <div id=\"aiBarWarn\" class=\"aibar-note warn\" hidden></div>\n      <div id=\"aiBarErr\" class=\"aibar-note adc-err\" hidden></div>\n      <div class=\"aibar-caps\" id=\"aiBarCaps\" hidden></div>\n      <div class=\"aibar-msgs\" id=\"aiBarMsgs\" aria-live=\"polite\">\n        <div class=\"aibar-welcome\" id=\"aiBarWelcome\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"\">\n          <h3>你好，我是 Dragon Claw</h3>\n          <p>NetCare 运营数字人助理。可以直接查询业务库与应用库、做统计分析；新增、修改、删除应用数据前都会先请你确认。</p>\n          <div class=\"aibar-chips\">\n            <button class=\"aibar-chip\" type=\"button\" data-q=\"你能访问哪些数据表？分别是做什么的？\"><span data-i=\"database\"></span>能访问哪些表</button>\n            <button class=\"aibar-chip\" type=\"button\" data-q=\"统计业务库风险任务按地区部的数量分布\"><span data-i=\"chart\"></span>风险任务分布</button>\n            <button class=\"aibar-chip\" type=\"button\" data-q=\"列出应用库中所有报告模板及其状态\"><span data-i=\"file\"></span>报告模板一览</button>\n          </div>\n        </div>\n      </div>\n      <div class=\"aibar-io\">\n        <div class=\"aibar-composer\">\n          <textarea id=\"aiBarQ\" rows=\"1\" placeholder=\"问我运营数据问题，或让我整理报告…\" spellcheck=\"false\"></textarea>\n          <div class=\"aibar-composer-f\">\n            <label class=\"aibar-switch\" title=\"开启后 Dragon Claw 可调用数据库能力；写操作仍需你确认\"><input type=\"checkbox\" id=\"aiBarAgent\" checked><i></i>数据能力</label>\n            <span class=\"aibar-kbd\">Enter 发送 · Shift+Enter 换行</span>\n            <button class=\"aibar-send\" id=\"aiBarSend\" type=\"button\" disabled title=\"发送\" data-i=\"send\"></button>\n          </div>\n        </div>\n      </div>\n      <div class=\"aibar-frame-h\">\n        <span class=\"lbl\"><span data-i=\"window\"></span>原 ADC 聊天页</span>\n        <div class=\"spacer\"></div>\n        <select id=\"aiBarFrameZoom\" class=\"aibar-zoom\" title=\"嵌入 ADC 聊天页缩放（50/70/100，跟随浮窗尺寸）\">\n          <option value=\"50\" selected>50%</option>\n          <option value=\"70\">70%</option>\n          <option value=\"100\">100%</option>\n        </select>\n        <button class=\"aibar-link\" id=\"aiBarFrameToggle\" type=\"button\">展开</button>\n      </div>\n      <div id=\"aiBarFrameWrap\">\n        <iframe id=\"aiBarFrame\" title=\"ADC 原聊天页\"></iframe>\n      </div>\n      <div class=\"aibar-br\" id=\"aiBarBr\" title=\"拖动调整窗口大小\"></div>\n    </aside>\n\n    <!-- 侧栏收起时的悬浮展开按钮 -->\n    <button id=\"aiBarFab\" type=\"button\" title=\"展开 Dragon Claw 助手\"><img src=\"data:image/jpeg;base64,\" alt=\"\"><span>Dragon Claw</span><span class=\"fab-dot\"></span></button>\n  \n  </div>\n\n  <div class=\"foot\">AiOps-Report · 与工程同源部署 · 无第三方依赖 · <span style=\"font-weight:600\">v1.4.4</span></div>\n\n  <script src=\"shared/icons.js\"></script>\n\n<script>\n\n/* ================= 端点定义（含数据链路元信息） ================= */\nconst L = {\n  APP_R:{cls:'read',  label:'应用·读', facade:'query_app_schema()', base:'POST /api/dh/query', apiNo:'API-Q1', target:'应用 Schema',\n         inReq:'datasourceId + schema(应用UUID) + sql + limit', out:'data.rows[]（dict 列表）',\n         nodes:['base','db'],\n         plain:'数据在「本应用自己的库」（应用 Schema，即这个应用名下的 5 张月报管理表，如 t_report_template / t_report_block）。本应用对自己的库可随便读写，但代码里没有任何数据库账号密码——由后端在服务器上调基座平台的查询接口（API-Q1）取数，基座去库里查完再把行返回。'},\n  APP_W:{cls:'write', label:'应用·写', facade:'execute_app_schema()', base:'POST /api/dh/execute', apiNo:'API-Q2', target:'应用 Schema',\n         inReq:'datasourceId + schema + 写SQL (INSERT/UPDATE/DELETE) + 身份头 x-app-id', out:'data.affectedRows',\n         nodes:['base','db'],\n         plain:'往「本应用自己的库」写数据。基座只允许 INSERT / UPDATE / DELETE，不能建表改表；每次写操作都带应用身份头（x-app-id，基座启动时自动注入，代码不用管），基座校验「谁在写」——只能写自己的库，写别人应用的库或业务库会被拒绝。'},\n  BIZ:{cls:'biz',     label:'业务库·读', facade:'query_business()', base:'POST /api/dh/query', apiNo:'API-Q1', target:'业务库 netcare（只读）',\n         inReq:'datasourceName(业务库组名) + sql + limit（不带 schema）', out:'data.rows[]',\n         nodes:['base','db'],\n         plain:'数据来自运营业务库 netcare（400+ 张表：工单、整改、风险、EOS 退网等真实运营数据）。本应用对它是只读的，永远改不了里面的数据；后端在服务器上调基座查询接口（API-Q1），用「业务库组名」路由，基座去查完把行返回。'},\n  HEALTH:{cls:'health',label:'健康检查', facade:'check_base_api()', base:'GET /api/dh/query/datasources', apiNo:'API-Q3', target:'基座服务',\n         inReq:'无（GET 探活）', out:'{code, data[]数据源列表}',\n         nodes:['base'],\n         plain:'不查任何业务数据，只是问基座一句「你在吗」（API-Q3 返回配置的数据源列表）。通了 → 页面顶部健康灯亮绿；不通 → 亮红，提示当前查不了数据但服务本身没挂。'},\n  LOCAL:{cls:'local', label:'本地静态', facade:'（无 DB 调用）', base:'—', apiNo:'—', target:'内存常量',\n         inReq:'无', out:'预置指标集',\n         nodes:[],\n         plain:'完全不碰数据库。数据是打包在工程里的预置常量或静态 JSON 文件（如《运营指标-索引目录》映射），后端直接从内存返回，最快、也永远可用。'},\n  ADC:{cls:'local', label:'云端·AI', facade:'ADCChat v1.4（浏览器直连）', base:'POST /adc-agent/.../stream', apiNo:'—', target:'ADC 数字人（外部 SSE）',\n       inReq:'message + session_id（首次自动捕获）+ 动态 CSRF + x-adc-page-* 校验头', out:'SSE 流式助手正文',\n       nodes:[],\n       plain:'不走本应用后端、不查任何库：浏览器直接 POST 到 ADC 数字人的 SSE 流接口（credentials 带当前登录 Cookie）。v1.4 只需提问——首次提问自动借用卡内 iframe 的原 ADC 聊天页发送并捕获会话/校验头（测试/生产双环境自动识别），之后直连。硬性同源约束——只有本工程上传数字人云端后（与 ADC 同 origin）才能真实问答；本地 127.0.0.1 只能预览页面。'},\n};\n\n/* 每个接口的白话说明（右侧「数据链路说明」卡片展示）：表特征 / 转换方式 / 逻辑 */\nconst EXPLAIN = {\n  'GET /healthz':'不查业务数据。后端调基座「数据源列表」接口（API-Q3）看能否连通：能连通返回 ok，不能返回 fail，页面顶部健康灯随它变色。',\n  'GET /reports':'读报告模板表 t_report_template，一行 = 一份报告（名称 / 描述 / 状态）。无关联、无加工，按创建时间倒序返回。',\n  'POST /reports':'往模板表插入一条新记录，请求体带名称 / 描述 / 状态（默认草稿 draft），返回新记录 id。',\n  'GET /reports/{id}':'一次读三张表再拼装：模板表（基本信息）+ 区块表 t_report_block（有哪些小节、每节图表类型、顺序）+ 配置表 t_report_config（透视哪些维度 / 哪些度量），组装成「报告详情」返回。',\n  'PUT /reports/{id}':'部分更新：请求体里带哪个字段就更新哪个（如把状态从 draft 改成 published），其他字段不动。',\n  'DELETE /reports/{id}':'按 id 删除对应报告。',\n  'POST /reports/{id}/blocks':'整体替换策略：先删掉该报告现有全部区块，再把请求体里的区块列表整体插入。保证库里和前端展示永远一致，不会残留旧区块。',\n  'PUT /reports/{id}/configs':'幂等写入：配置不存在就插入，存在就更新，重复提交不会产生重复行。config_text 是一段 JSON，存「透视维度 + 度量定义」。',\n  'POST /reports/{id}/render':'与「报告详情」读同一份数据（模板 + 区块 + 配置），供预览 / 生成报告场景使用，只读不写库。',\n  'GET /data-elements':'读 t_data_element 全部数据元素。数据元素是本工程的核心概念：一个「业务指标」= 去哪个库、哪张表、取哪些列（source_db + source_table + field_select）。',\n  'GET /data-elements/grouped':'与列表同一个数据，但后端按 category（类别）分组返回，方便前端直接渲染成下拉分组。',\n  'POST /data-elements':'新建一个指标：必须指定来源表（source_table）和选中字段（field_select：字段 + 展示别名数组）。建好后就能用 /data/fetch 按它的 id 取数。',\n  'GET /data-elements/{id}':'按 id 读一条元素。',\n  'PUT /data-elements/{id}':'部分更新：请求体里带哪个字段就更新哪个。',\n  'DELETE /data-elements/{id}':'按 id 删除元素。',\n  'GET /data-sources':'读数据来源表 t_data_source：登记「数据从哪里来」（类型：static 静态 / 业务库等）。',\n  'POST /data-sources':'新建一条来源登记。',\n  'GET /data-sources/{id}':'按 id 读一条来源。',\n  'PUT /data-sources/{id}':'部分更新。',\n  'DELETE /data-sources/{id}':'按 id 删除。',\n  'GET /data/tables?source_db=netcare':'查业务库的「自己的目录」information_schema.TABLES，返回 400+ 张表名 + 中文备注。这也是「全表盘点」的底表清单来源。',\n  'GET /data/columns/{table}?source_db=netcare':'查业务库 information_schema.COLUMNS，返回指定表的字段名 / 类型 / 中文注释。「点击表看列」和「源表直查」的过滤列校验都用它。',\n  'GET /data/indicators/default':'返回内置默认指标集（代码里的预置常量），不查库。',\n  'POST /data/fetch':'核心取数接口，三步转换：① 按 element_id 查 t_data_element 拿到来源表 + 选中列；② 结合时间 / 地区参数拼出查询 SQL；③ 路由到业务库只读执行。表单表格类元素返回行集合，指标类元素返回单个数值。',\n  'POST /data/pivot':'取数逻辑同 fetch，再追加 GROUP BY 维度 + 聚合函数（count / sum / max …），用于饼图 / 柱状图这类图表场景。',\n  'GET /data/table-map':'返回《运营指标-索引目录》整份映射（打包在工程里的静态 JSON：22 个模块，每个含上游源表 + 业务库落地表），不查库。',\n  'GET /data/table-map/lookup?name=risk_task_new':'输入一个表名，在映射文件里查，返回：它属于哪个模块、上游源表是什么、对应业务库里哪几张落地表。',\n  'GET /data/table-map/data?name=risk_task_new&limit=20':'源表直查的底层接口。关键转换：源表在上游库、本应用够不着 → 自动换成对应的业务库落地表 → 拼上过滤条件 / 列选择 / 行数限制生成 SQL → 走业务库只读执行（行数「不限」时按 1000 行/页自动翻页取完）。',\n  '★ 源表直查':'上面的工具页面：调 lookup 确认映射 → 调 /data/table-map/data 取数 → 前端渲染成表格；过滤条件 / 列选择 / 行数都作为参数传给后端；切换落地表时先校验过滤列是否存在。',\n  '★ 全表盘点':'对工程提到的每张表逐个体检：① 查 information_schema 的存在性 / 中文备注 / 估算行数 / 字段数；② 取前 20 行样例数据；③ 核对归属（源表 / 落地表 / 应用表 / 业务清单底稿）。',\n  '★ 自由请求':'把用户输入的任意 method / path / body 原样转发给对应端点，没有固定业务逻辑；结果展示在下方「响应输出」。',\n  '★ AI 问答':'Dragon Claw 助理：对话经 ADC 数字人（v1.4 一体版）完成，首次提问由浮窗内嵌的原 ADC 聊天页自动建立会话，之后浏览器直连 SSE。开启「数据能力」后，页面把 /api/agent/capabilities 的工具协议发给模型；模型输出 dragon-action 动作块，页面调用 /api/agent/execute 执行（业务库只读，应用表写入需用户确认并记审计），再把结果回传给模型。仅部署到与 ADC 同源的云端后才能真实问答。',\n};\n\nconst CUSTOM_GROUP={ key:'custom', name:'自定义查询', icon:ICON.star, eps:[] };\nconst GROUPS = [\n  CUSTOM_GROUP,\n  { key:'health', name:'健康检查', icon:ICON.pulse, eps:[\n    { m:'GET', p:'/healthz', name:'探活', desc:'检查基座 API 是否连通', link:L.HEALTH },\n  ]},\n  { key:'reports', name:'报告 Reports', icon:ICON.file, eps:[\n    { m:'GET', p:'/reports', name:'报告列表', desc:'全部报告（按创建时间倒序）', link:L.APP_R },\n    { m:'POST', p:'/reports', name:'创建报告', desc:'新建一条报告模板', body:{name:'测试报告',title:'',description:'',status:'draft'}, link:L.APP_W },\n    { m:'GET', p:'/reports/{id}', name:'报告详情', desc:'含区块+配置（3 表并发查询）', params:[{k:'id',v:1}], link:L.APP_R },\n    { m:'PUT', p:'/reports/{id}', name:'更新报告', desc:'部分字段更新', params:[{k:'id',v:1}], body:{status:'published'}, link:L.APP_W },\n    { m:'DELETE', p:'/reports/{id}', name:'删除报告', desc:'按 id 删除', params:[{k:'id',v:1}], link:L.APP_W },\n    { m:'POST', p:'/reports/{id}/blocks', name:'保存区块', desc:'整体替换报告区块列表', params:[{k:'id',v:1}], body:[{block_key:'b1',block_title:'第一节',chart_type:'none',order_no:0}], link:L.APP_W },\n    { m:'PUT', p:'/reports/{id}/configs', name:'保存配置', desc:'区块透视/样式配置（幂等）', params:[{k:'id',v:1}], body:{block_id:1,section:'process',config_text:{dim_fields:['region_code'],metrics:[{field:'cnt',agg:'count',label:'数量'}]}}, link:L.APP_W },\n    { m:'POST', p:'/reports/{id}/render', name:'渲染报告', desc:'预览/生成用（读详情）', params:[{k:'id',v:1}], link:L.APP_R },\n  ]},\n  { key:'air', name:'AI 月报 AI Report', icon:ICON.sparkles, eps:[\n    { m:'GET', p:'/air/documents', name:'月报列表', desc:'全部 AI 月报（id / 名称 / 报告月份）', link:L.APP_R },\n    { m:'GET', p:'/air/documents/{id}/outline', name:'月报大纲', desc:'章节、格子 id、格子名、宽度、提示词', params:[{k:'id',v:2}], link:L.APP_R },\n    { m:'GET', p:'/air/documents/{id}', name:'完整月报', desc:'含对话、配方与本月结果', params:[{k:'id',v:2}], link:L.APP_R },\n    { m:'POST', p:'/air/documents/{id}/cells', name:'新增格子', desc:'默认加到最后一个章节，可传 chapter_id', params:[{k:'id',v:2}], body:{prompt:'统计本月风险任务按地区部的数量，柱状图，附一句总结',span:6}, link:L.APP_W },\n    { m:'PUT', p:'/air/documents/{id}/cells/{cell}', name:'修改格子', desc:'提示词 / 宽度(1-12) / 高度', params:[{k:'id',v:2},{k:'cell',v:'cell-xxxx'}], body:{prompt:'改后的提示词',span:12}, link:L.APP_W },\n    { m:'DELETE', p:'/air/documents/{id}/cells/{cell}', name:'删除格子', desc:'连同提示词、配方、结果', params:[{k:'id',v:2},{k:'cell',v:'cell-xxxx'}], link:L.APP_W },\n    { m:'PUT', p:'/air/documents/{id}/style', name:'整体风格提示词', desc:'每个格子生成时都遵守', params:[{k:'id',v:2}], body:{prompt:'【风格与配色】\\n- 深蓝商务风格'}, link:L.APP_W },\n    { m:'DELETE', p:'/air/documents/{id}', name:'删除月报', desc:'连同格子与配置行', params:[{k:'id',v:2}], link:L.APP_W },\n    { m:'POST', p:'/air/run-data', name:'配方取数', desc:'按报告月份执行 SQL 来源（{{month}} 等占位符）', body:{month:'2026-09',recipe:{sources:[{id:'s1',kind:'sql',source:'netcare',sql:\"SELECT region_name, COUNT(*) AS n FROM risk_task WHERE period_month = '{{month}}' GROUP BY region_name\"}]}}, link:L.BIZ },\n    { m:'GET', p:'/air/month-values?month=2026-09', name:'月份占位符', desc:'某个报告月份下各占位符的取值', link:L.LOCAL },\n    { m:'GET', p:'/agent/capabilities', name:'AI 能力清单', desc:'Dragon Claw 可调用的工具与协议', link:L.LOCAL },\n  ]},\n  { key:'elements', name:'数据元素 Data Elements', icon:ICON.layers, eps:[\n    { m:'GET', p:'/data-elements', name:'元素列表', desc:'全部数据元素', link:L.APP_R },\n    { m:'GET', p:'/data-elements/grouped', name:'分组元素', desc:'按 category 分组', link:L.APP_R },\n    { m:'POST', p:'/data-elements', name:'创建元素', desc:'新增一个数据元素', body:{element_key:'demo_el',name:'示例元素',category:'默认',data_kind:'form',source_db:'netcare',source_table:'risk_task',field_select:[{field:'region_name',alias:'地区部'}],time_field:'period_month'}, link:L.APP_W },\n    { m:'GET', p:'/data-elements/{id}', name:'元素详情', desc:'按 id 获取', params:[{k:'id',v:1}], link:L.APP_R },\n    { m:'PUT', p:'/data-elements/{id}', name:'更新元素', desc:'部分字段更新', params:[{k:'id',v:1}], body:{description:'更新说明'}, link:L.APP_W },\n    { m:'DELETE', p:'/data-elements/{id}', name:'删除元素', desc:'按 id 删除', params:[{k:'id',v:1}], link:L.APP_W },\n  ]},\n  { key:'sources', name:'数据来源 Data Sources', icon:ICON.database, eps:[\n    { m:'GET', p:'/data-sources', name:'来源列表', desc:'全部数据来源', link:L.APP_R },\n    { m:'POST', p:'/data-sources', name:'创建来源', desc:'新增数据来源', body:{source_key:'demo_src',name:'示例来源',source_type:'static',description:''}, link:L.APP_W },\n    { m:'GET', p:'/data-sources/{id}', name:'来源详情', desc:'按 id 获取', params:[{k:'id',v:1}], link:L.APP_R },\n    { m:'PUT', p:'/data-sources/{id}', name:'更新来源', desc:'部分字段更新', params:[{k:'id',v:1}], body:{name:'改名'}, link:L.APP_W },\n    { m:'DELETE', p:'/data-sources/{id}', name:'删除来源', desc:'按 id 删除', params:[{k:'id',v:1}], link:L.APP_W },\n  ]},\n  { key:'data', name:'数据查询 Data', icon:ICON.chart, eps:[\n    { m:'GET', p:'/data/tables?source_db=netcare', name:'表列表', desc:'业务库下所有表（information_schema）', link:L.BIZ },\n    { m:'GET', p:'/data/columns/{table}?source_db=netcare', name:'字段列表', desc:'某表的字段/类型/注释', params:[{k:'table',v:'risk_task'}], link:L.BIZ },\n    { m:'GET', p:'/data/indicators/default', name:'默认指标集', desc:'预置指标（本地常量）', link:L.LOCAL },\n    { m:'POST', p:'/data/fetch', name:'按元素取数', desc:'表单表格 / 指标单值', body:{element_id:1,start:'2026-01',end:'2026-12',region_code:'',repoffice_code:''}, link:L.BIZ },\n    { m:'POST', p:'/data/pivot', name:'数据透视', desc:'GROUP BY 维度 + 聚合度量', body:{element_id:1,dim_field:'region_code',metric_field:'',agg:'count',start:'',end:'',limit:20}, link:L.BIZ },\n  ]},\n  { key:'map', name:'表映射 Table Map', icon:ICON.map, eps:[\n    { m:'GET', p:'/data/table-map', name:'完整映射', desc:'22 个索引目录模块 + 源表 + 业务库落地表', link:L.LOCAL },\n    { m:'GET', p:'/data/table-map/lookup?name=risk_task_new', name:'解析表名', desc:'单个表名 → 所属模块 / 源表 / 落地表', link:L.LOCAL },\n    { m:'GET', p:'/data/table-map/data?name=risk_task_new&limit=20', name:'源表数据接口', desc:'源表直查底层 API（过滤/列选见「工具 → 源表直查」）', link:L.BIZ },\n  ]},\n  { key:'tools', name:'工具', icon:ICON.wrench, eps:[\n    { m:'★', p:'源表直查', name:'源表 → 落地表映射 + 数据查询', desc:'过滤条件 / 列选择 / 不限行数', kind:'src', link:L.BIZ },\n    { m:'★', p:'全表盘点', name:'所有表盘点 / 单表体检 / 前20行', desc:'source+landing+biz+元素表 全量校验', kind:'audit', link:L.BIZ },\n    { m:'★', p:'自由请求', name:'任意 method / path / body', desc:'临时探索用', kind:'free', link:L.LOCAL },\n    { m:'★', p:'AI 问答', name:'Dragon Claw AI 助理（可调用数据能力）', desc:'对话查数 / 统计 / 经确认后修改应用数据', kind:'adc', link:L.ADC },\n  ]},\n];\n\n/* ================= 快捷测试用例库（仅写入类端点） =================\n  key  = method + ' ' + path（与 EXPLAIN 一致，如 'POST /reports'、'PUT /reports/{id}'）\n  每个用例：\n    label  → 按钮文字\n    body   → 填入请求体 JSON（POST/PUT 有 body 时有效）\n    params → 填入路径参数输入框（如 {id:5}）\n    edge   → true 标橙色（边界 / 非法数据，测后端校验）\n    del    → true 标红色（删除操作）\n  点击 = 填充 + （勾选时）自动发送 */\nconst QUICK_TESTS = {\n  'POST /reports': [\n    { label:'最小·仅名称', body:{name:'快速测试报告'} },\n    { label:'完整字段', body:{name:'完整测试报告',title:'月度运营报告',description:'自动化测试生成的报告模板',status:'draft'} },\n    { label:'直接发布', body:{name:'发布态报告',title:'',description:'',status:'published'} },\n    { label:'特殊字符', body:{name:'测试<>\"&\\'特殊',title:'含/斜杠',description:'换行\\n制表\\t中文「」',status:'draft'} },\n    { label:'超长名称', body:{name:'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA',title:'',description:'',status:'draft'} },\n    { label:'Emoji', body:{name:'📊报告📈测试🐉',title:'',description:'含 emoji 的描述 🎉',status:'draft'} },\n    { label:'空名称(边界)', body:{name:'',title:'',description:'',status:'draft'}, edge:true },\n    { label:'数字名称', body:{name:12345,title:'',description:'',status:'draft'}, edge:true },\n    { label:'null字段', body:{name:null,title:null,description:null,status:'draft'}, edge:true },\n  ],\n  'PUT /reports/{id}': [\n    { label:'→草稿', body:{status:'draft'} },\n    { label:'→发布', body:{status:'published'} },\n    { label:'→归档', body:{status:'archived'} },\n    { label:'改名', body:{name:'已更新名称'} },\n    { label:'改描述', body:{description:'这是更新后的描述文字'} },\n    { label:'清空描述', body:{description:''} },\n    { label:'改标题', body:{title:'新标题'} },\n    { label:'多字段同改', body:{name:'新名',description:'新描述',status:'draft',title:'新标题'} },\n    { label:'非法状态值', body:{status:'invalid_status'}, edge:true },\n  ],\n  'DELETE /reports/{id}': [\n    { label:'删 id=1', params:{id:1}, del:true },\n    { label:'删 id=2', params:{id:2}, del:true },\n    { label:'删 id=3', params:{id:3}, del:true },\n    { label:'删不存在', params:{id:99999}, del:true, edge:true },\n    { label:'删 id=0', params:{id:0}, del:true, edge:true },\n    { label:'删负数', params:{id:-1}, del:true, edge:true },\n  ],\n  'POST /reports/{id}/blocks': [\n    { label:'单区块', body:[{block_key:'b1',block_title:'概述',chart_type:'none',order_no:0}] },\n    { label:'多区块', body:[\n      {block_key:'b1',block_title:'概述',chart_type:'none',order_no:0},\n      {block_key:'b2',block_title:'趋势图',chart_type:'line',order_no:1},\n      {block_key:'b3',block_title:'占比',chart_type:'pie',order_no:2},\n    ]},\n    { label:'柱状图', body:[{block_key:'b1',block_title:'对比',chart_type:'bar',order_no:0}] },\n    { label:'表格', body:[{block_key:'b1',block_title:'明细',chart_type:'table',order_no:0}] },\n    { label:'5区块', body:[\n      {block_key:'b1',block_title:'第一节',chart_type:'none',order_no:0},\n      {block_key:'b2',block_title:'第二节',chart_type:'line',order_no:1},\n      {block_key:'b3',block_title:'第三节',chart_type:'bar',order_no:2},\n      {block_key:'b4',block_title:'第四节',chart_type:'pie',order_no:3},\n      {block_key:'b5',block_title:'第五节',chart_type:'table',order_no:4},\n    ]},\n    { label:'清空区块', body:[], edge:true },\n    { label:'缺block_key', body:[{block_title:'无key',chart_type:'none',order_no:0}], edge:true },\n  ],\n  'PUT /reports/{id}/configs': [\n    { label:'简单透视', body:{block_id:1,section:'process',config_text:{dim_fields:['region_code'],metrics:[{field:'cnt',agg:'count',label:'数量'}]}} },\n    { label:'多维度', body:{block_id:1,section:'process',config_text:{dim_fields:['region_code','repoffice_code'],metrics:[{field:'cnt',agg:'count',label:'数量'},{field:'amount',agg:'sum',label:'金额'}]}} },\n    { label:'最大值聚合', body:{block_id:1,section:'result',config_text:{dim_fields:['period_month'],metrics:[{field:'value',agg:'max',label:'峰值'}]}} },\n    { label:'平均值', body:{block_id:1,section:'overview',config_text:{dim_fields:['region_code'],metrics:[{field:'score',agg:'avg',label:'均分'}]}} },\n    { label:'空配置', body:{block_id:1,section:'',config_text:{}}, edge:true },\n    { label:'字符串config', body:{block_id:1,section:'process',config_text:'{\"dim\":\"region\"}'}, edge:true },\n  ],\n  'POST /data-elements': [\n    { label:'表单类', body:{element_key:'qk_form',name:'快捷表单元素',category:'默认',data_kind:'form',source_db:'netcare',source_table:'risk_task',field_select:[{field:'region_name',alias:'地区部'}],time_field:'period_month'} },\n    { label:'指标类', body:{element_key:'qk_metric',name:'快捷指标元素',category:'默认',data_kind:'metric',source_db:'netcare',source_table:'risk_task',field_select:[{field:'cnt',alias:'数量'}],time_field:'period_month'} },\n    { label:'多字段', body:{element_key:'qk_multi',name:'多字段元素',category:'风险',data_kind:'form',source_db:'netcare',source_table:'risk_task',field_select:[{field:'region_name',alias:'地区部'},{field:'repoffice_name',alias:'代表处'},{field:'cnt',alias:'数量'}],time_field:'period_month'} },\n    { label:'整改表', body:{element_key:'qk_rect',name:'整改元素',category:'整改',data_kind:'form',source_db:'netcare',source_table:'rect_task',field_select:[{field:'region_name',alias:'地区部'}],time_field:'period_month'} },\n    { label:'License表', body:{element_key:'qk_lic',name:'License元素',category:'License',data_kind:'form',source_db:'netcare',source_table:'license_info',field_select:[{field:'region_name',alias:'地区部'}],time_field:'period_month'} },\n    { label:'最小字段', body:{element_key:'qk_min',name:'最小元素',category:'默认',data_kind:'form',source_db:'netcare',source_table:'risk_task',field_select:[{field:'id',alias:'ID'}]} },\n    { label:'缺source_table', body:{element_key:'qk_bad',name:'缺表',category:'默认',data_kind:'form',source_db:'netcare',field_select:[{field:'id',alias:'ID'}]}, edge:true },\n    { label:'空field_select', body:{element_key:'qk_empty',name:'空字段',category:'默认',data_kind:'form',source_db:'netcare',source_table:'risk_task',field_select:[]}, edge:true },\n  ],\n  'PUT /data-elements/{id}': [\n    { label:'改名称', body:{name:'更新后名称'} },\n    { label:'改类别→风险', body:{category:'风险'} },\n    { label:'改类别→整改', body:{category:'整改'} },\n    { label:'改描述', body:{description:'快捷更新说明'} },\n    { label:'改表', body:{source_table:'rect_task'} },\n    { label:'改kind', body:{data_kind:'metric'} },\n    { label:'多字段', body:{name:'新名',category:'整改',description:'批量更新'} },\n    { label:'改字段选择', body:{field_select:[{field:'region_name',alias:'地区'},{field:'cnt',alias:'数'}]} },\n  ],\n  'DELETE /data-elements/{id}': [\n    { label:'删 id=1', params:{id:1}, del:true },\n    { label:'删 id=2', params:{id:2}, del:true },\n    { label:'删 id=3', params:{id:3}, del:true },\n    { label:'删不存在', params:{id:99999}, del:true, edge:true },\n    { label:'删 id=0', params:{id:0}, del:true, edge:true },\n  ],\n  'POST /data-sources': [\n    { label:'静态', body:{source_key:'qk_static',name:'快捷静态源',source_type:'static',description:''} },\n    { label:'业务库', body:{source_key:'qk_biz',name:'快捷业务源',source_type:'business',description:'netcare 业务库'} },\n    { label:'带描述', body:{source_key:'qk_desc',name:'带描述的源',source_type:'static',description:'这是一段描述文字'} },\n    { label:'空key', body:{source_key:'',name:'空key源',source_type:'static',description:''}, edge:true },\n    { label:'长描述', body:{source_key:'qk_long',name:'长描述源',source_type:'static',description:'这是一段非常长的描述文字'.repeat(10)} },\n  ],\n  'PUT /data-sources/{id}': [\n    { label:'改名', body:{name:'改名后'} },\n    { label:'改类型→业务', body:{source_type:'business'} },\n    { label:'改类型→静态', body:{source_type:'static'} },\n    { label:'改描述', body:{description:'更新描述'} },\n    { label:'多字段', body:{name:'新名',description:'新描述'} },\n    { label:'改key', body:{source_key:'updated_key'} },\n  ],\n  'DELETE /data-sources/{id}': [\n    { label:'删 id=1', params:{id:1}, del:true },\n    { label:'删 id=2', params:{id:2}, del:true },\n    { label:'删 id=3', params:{id:3}, del:true },\n    { label:'删不存在', params:{id:99999}, del:true, edge:true },\n    { label:'删 id=0', params:{id:0}, del:true, edge:true },\n  ],\n};\n\n/* ================= 状态 & 工具 ================= */\nconst $ = s => document.querySelector(s);\nlet current = null;   // 当前选中端点\nlet lastResp = null;  // 最近一次响应（用于格式切换重渲染）\nlet respFmt = 'json'; // 响应输出格式：json / tree / table\n\n/* ================= 查询结果缓存（sessionStorage，切换端点后切回免重查） ================= */\nconst CACHE_PREFIX='api_test_res_';\nfunction cacheKeyOf(method,url,bodyText){\n  let bt=(bodyText&&bodyText.trim())?bodyText:'';\n  try{ bt=JSON.stringify(JSON.parse(bt)).slice(0,800); }catch(e){ bt=bt.slice(0,800); }\n  return method.toUpperCase()+' '+url+'|'+bt;\n}\nfunction cacheSave(key,r,respFmtVal){\n  try{ sessionStorage.setItem(CACHE_PREFIX+key, JSON.stringify({t:Date.now(),f:respFmtVal||respFmt,r})); }catch(e){/* 超配额忽略 */}\n}\nfunction cacheGet(key){\n  try{ const s=sessionStorage.getItem(CACHE_PREFIX+key); return s?JSON.parse(s):null; }catch(e){ return null; }\n}\nfunction clearCache(){\n  Object.keys(sessionStorage).filter(k=>k.startsWith(CACHE_PREFIX)).forEach(k=>sessionStorage.removeItem(k));\n}\nfunction cacheBadgeHtml(t){\n  const m=Math.round((Date.now()-t)/60000);\n  const txt = m<1 ? '刚刚' : (m<60 ? m+' 分钟前' : new Date(t).toLocaleString());\n  return '<span class=\"cache-badge\">🕘 缓存 '+esc(txt)+' · <button class=\"cache-re\" type=\"button\">↻ 重新查询</button></span>';\n}\n\nfunction esc(s){return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}\n\n// JSON 高亮\nfunction hlJSON(obj){\n  let s = JSON.stringify(obj, null, 2);\n  s = esc(s);\n  return s.replace(/(\"(\\\\u[a-zA-Z0-9]{4}|\\\\[^u]|[^\\\\\"])*\"(\\s*:)?|\\b(true|false)\\b|\\bnull\\b|-?\\d+(\\.\\d+)?([eE][+\\-]?\\d+)?)/g, m=>{\n    let cls='j-n';\n    if(/^\"/.test(m)) cls = /:$/.test(m)?'j-k':'j-s';\n    else if(/true|false/.test(m)) cls='j-b';\n    else if(/null/.test(m)) cls='j-null';\n    return '<span class=\"'+cls+'\">'+m+'</span>';\n  });\n}\n\n// API 基地址：优先同源（当前目录 + api）\nfunction defaultBase(){\n  return new URL('api',document.baseURI).pathname;\n}\n$('#apiBase').value = defaultBase();\nfunction base(){ return $('#apiBase').value.replace(/\\/+$/,''); }\n\n/* ================= 主题化弹窗（替代浏览器原生 alert/confirm/prompt，Promise 化） ================= */\nlet _dlgResolve=null;\nfunction _dlgHost(){\n  let h=document.getElementById('dlgHost');\n  if(!h){\n    h=document.createElement('div'); h.id='dlgHost';\n    h.innerHTML='<div class=\"dlg-mask\" hidden><div class=\"dlg\" role=\"dialog\" aria-modal=\"true\"></div></div>';\n    document.body.appendChild(h);\n    h.querySelector('.dlg-mask').addEventListener('mousedown',e=>{\n      if(e.target===e.currentTarget && _dlgResolve && !h.querySelector('.dlg').classList.contains('no-backdrop')) _dlgResolve(null);\n    });\n    document.addEventListener('keydown',e=>{ if(e.key==='Escape' && _dlgResolve) _dlgResolve(null); });\n  }\n  return h;\n}\nfunction _dlgOpen(node, opts){\n  opts=opts||{};\n  const h=_dlgHost(), mask=h.querySelector('.dlg-mask'), box=h.querySelector('.dlg');\n  box.innerHTML=''; box.classList.toggle('no-backdrop', !opts.backdropClose);\n  box.appendChild(node);\n  mask.hidden=false;\n  requestAnimationFrame(()=>mask.classList.add('show'));\n  _dlgResolve=function(v){\n    _dlgResolve=null;\n    mask.classList.remove('show');\n    setTimeout(()=>{ if(box.firstChild===node){ mask.hidden=true; box.innerHTML=''; } },180);\n    if(opts.onClose) opts.onClose(v);\n  };\n  const r=_dlgResolve;\n  if(opts.autoFocus) setTimeout(()=>{ try{ opts.autoFocus.focus(); }catch(e){} },60);\n  return r;\n}\n/* 输入弹窗：resolve 输入值（字符串）；取消/ESC/关闭 → null */\nfunction dlgPrompt(o){\n  o=o||{};\n  return new Promise(res=>{\n    const node=document.createElement('div');\n    node.innerHTML='<div class=\"dlg-h\"><span class=\"dlg-t\">'+esc(o.title||'输入')+'</span><button type=\"button\" class=\"dlg-x\" aria-label=\"关闭\">×</button></div>'\n      +'<div class=\"dlg-b\">'+(o.message?esc(o.message):'')\n      +'<input type=\"text\" class=\"dlg-inp\" spellcheck=\"false\" placeholder=\"'+esc(o.placeholder||'')+'\"></div>'\n      +'<div class=\"dlg-f\"><button type=\"button\" class=\"btn btn-ghost dlg-cancel\">取消</button><button type=\"button\" class=\"btn btn-primary dlg-ok\">确定</button></div>';\n    const inp=node.querySelector('.dlg-inp'), okB=node.querySelector('.dlg-ok');\n    inp.value=o.value||'';\n    let r, settled=false;\n    const done=v=>{ if(settled) return; settled=true; if(r) r(v); };\n    okB.onclick=()=>done(inp.value);\n    node.querySelector('.dlg-cancel').onclick=()=>done(null);\n    node.querySelector('.dlg-x').onclick=()=>done(null);\n    inp.addEventListener('keydown',e=>{ if(e.key==='Enter') done(inp.value); });\n    r=_dlgOpen(node,{autoFocus:inp, backdropClose:false, onClose:res});\n    setTimeout(()=>{ try{ inp.select(); }catch(e){} },80);\n  });\n}\n/* 确认弹窗：resolve true/false */\nfunction dlgConfirm(o){\n  o=o||{};\n  return new Promise(res=>{\n    const node=document.createElement('div');\n    node.innerHTML='<div class=\"dlg-h\"><span class=\"dlg-t\">'+esc(o.title||'确认')+'</span><button type=\"button\" class=\"dlg-x\" aria-label=\"关闭\">×</button></div>'\n      +(o.message?'<div class=\"dlg-b\">'+esc(o.message)+'</div>':'')\n      +'<div class=\"dlg-f\"><button type=\"button\" class=\"btn btn-ghost dlg-cancel\">'+esc(o.cancelText||'取消')+'</button><button type=\"button\" class=\"btn '+(o.danger?'btn-danger':'btn-primary')+' dlg-ok\">'+esc(o.okText||'确定')+'</button></div>';\n    const okB=node.querySelector('.dlg-ok');\n    let r, settled=false;\n    const done=v=>{ if(settled) return; settled=true; if(r) r(v); };\n    okB.onclick=()=>done(true);\n    node.querySelector('.dlg-cancel').onclick=()=>done(false);\n    node.querySelector('.dlg-x').onclick=()=>done(false);\n    node.addEventListener('keydown',e=>{ if(e.key==='Enter') done(true); });\n    r=_dlgOpen(node,{autoFocus:okB, backdropClose:true, onClose:res});\n  });\n}\n/* 提示弹窗：resolve true */\nfunction dlgAlert(o){\n  o=o||{};\n  return new Promise(res=>{\n    const node=document.createElement('div');\n    node.innerHTML='<div class=\"dlg-h\"><span class=\"dlg-t\">'+esc(o.title||'提示')+'</span><button type=\"button\" class=\"dlg-x\" aria-label=\"关闭\">×</button></div>'\n      +(o.message?'<div class=\"dlg-b\">'+esc(o.message)+'</div>':'')\n      +'<div class=\"dlg-f\"><button type=\"button\" class=\"btn btn-primary dlg-ok\">'+esc(o.okText||'知道了')+'</button></div>';\n    const okB=node.querySelector('.dlg-ok');\n    let r, settled=false;\n    const done=()=>{ if(settled) return; settled=true; if(r) r(true); };\n    okB.onclick=done;\n    node.querySelector('.dlg-x').onclick=done;\n    node.addEventListener('keydown',e=>{ if(e.key==='Enter') done(); });\n    r=_dlgOpen(node,{autoFocus:okB, backdropClose:true, onClose:res});\n  });\n}\n\n/* 全局成功提示 toast（右上角不遮挡内容，自动消失） */\nfunction toast(msg, ms){\n  ms=ms||3200;\n  let wEl=document.getElementById('toastWrap');\n  if(!wEl){ wEl=document.createElement('div'); wEl.id='toastWrap'; document.body.appendChild(wEl); }\n  const t=document.createElement('div'); t.className='toast'; t.innerHTML=msg;\n  wEl.appendChild(t);\n  requestAnimationFrame(()=>t.classList.add('show'));\n  setTimeout(()=>{ t.classList.remove('show'); setTimeout(()=>t.remove(),250); },ms);\n}\n\n/* ================= 渲染左侧端点列表 ================= */\nlet menuSearchKw = '';\nfunction epMatchSearch(ep, g){\n  if(!menuSearchKw) return true;\n  const kw = menuSearchKw;\n  const hay = (ep.p+' '+ep.name+' '+ep.desc+' '+g.name+' '+ep.link.label).toLowerCase();\n  return hay.includes(kw);\n}\nfunction renderLeft(){\n  const wrap = $('#leftPanel');\n  wrap.innerHTML='';\n  GROUPS.forEach((g,gi)=>{\n    if(g.key==='custom'){\n      // 自定义查询分组始终显示，即使为空也显示「暂无」提示\n      if(!g.eps.length){\n        const grp=document.createElement('div');\n        grp.className='grp';\n        grp.dataset.g=gi;\n        grp.innerHTML='<div class=\"grp-h\"><span class=\"caret\">▾</span><span class=\"gicon\">'+g.icon+'</span><span class=\"gname\">'+esc(g.name)+'</span><span class=\"cnt\">0</span></div><div class=\"grp-b\"><div class=\"hint\" style=\"padding:10px 12px;text-align:center;color:var(--text-3)\">暂无自定义查询<br><span style=\"font-size:11px\">在「源表直查」中点「保存为自定义」即可添加</span></div></div>';\n        grp.querySelector('.grp-h').onclick=()=>grp.classList.toggle('closed');\n        wrap.appendChild(grp);\n        return;\n      }\n    }\n    const matchedEps = g.eps.map((ep,ei)=>({ep,ei})).filter(({ep})=>epMatchSearch(ep,g));\n    if(menuSearchKw && matchedEps.length===0) return; // 搜索时隐藏无匹配分组\n    const grp=document.createElement('div');\n    grp.className='grp';\n    grp.dataset.g=gi;\n    grp.innerHTML='<div class=\"grp-h\"><span class=\"caret\">▾</span><span class=\"gicon\">'+g.icon+'</span><span class=\"gname\">'+esc(g.name)+'</span><span class=\"cnt\">'+(menuSearchKw?matchedEps.length:g.eps.length)+'</span></div><div class=\"grp-b\"></div>';\n    const b=grp.querySelector('.grp-b');\n    matchedEps.forEach(({ep,ei})=>{\n      const el=document.createElement('div');\n      el.className='ep';\n      el.dataset.g=gi; el.dataset.e=ei;\n      el.title = ep.desc || ep.name;\n      el.innerHTML='<span class=\"m '+ep.m+'\">'+ep.m+'</span>'+\n                   '<div class=\"ep-path\">'+esc(ep.p)+'</div>'+\n                   '<span class=\"tag '+ep.link.cls+'\">'+ep.link.label+'</span>';\n      el.onclick=()=>selectEp(gi,ei,el);\n      b.appendChild(el);\n    });\n    grp.querySelector('.grp-h').onclick=()=>grp.classList.toggle('closed');\n    wrap.appendChild(grp);\n  });\n  if(menuSearchKw && !wrap.children.length){\n    wrap.innerHTML='<div class=\"hint\" style=\"padding:16px 12px;text-align:center\">无匹配接口</div>';\n  }\n}\n\n/* ================= 选中端点 → 填充请求区 ================= */\nfunction selectEp(gi,ei,el){\n  document.querySelectorAll('.ep.active').forEach(x=>x.classList.remove('active'));\n  el.classList.add('active');\n  const ep=GROUPS[gi].eps[ei];\n  current=ep;\n\n  $('#emptyHint').hidden=true;\n  renderChainCard(ep);\n\n  // 工具页（源表直查 / 全表盘点 / 自由请求 / AI 问答）：只显示对应卡片\n  if(ep.kind){\n    $('#reqCard').hidden=true;\n    $('#srcCard').hidden = (ep.kind!=='src' && ep.kind!=='custom');\n    $('#freeCard').hidden = ep.kind!=='free';\n    $('#auditCard').hidden = ep.kind!=='audit';\n    $('#adcCard').hidden = ep.kind!=='adc';\n    if(ep.kind==='src'){ $('#statCard').hidden=true; $('#respCard').hidden=true; $('#srcCustomTip').hidden=true; if(typeof curCustom!=='undefined') curCustom=null; }\n    if(ep.kind==='custom'){ $('#statCard').hidden=true; $('#respCard').hidden=true; applyCustomQuery(ep.cid); }\n    if(ep.kind==='audit'){ $('#statCard').hidden=true; $('#respCard').hidden=true; loadAudit(); }\n    if(ep.kind==='adc'){ $('#statCard').hidden=true; $('#respCard').hidden=true; if(window.__openAiBar) window.__openAiBar(); }\n    return;\n  }\n  $('#srcCard').hidden=true; $('#freeCard').hidden=true; $('#auditCard').hidden=true; $('#adcCard').hidden=true;\n\n  $('#reqCard').hidden=false;\n\n  // method + path\n  const ms=$('#methodSel'); ms.innerHTML='';\n  ['GET','POST','PUT','DELETE'].forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;ms.appendChild(o);});\n  ms.value=ep.m;\n  $('#pathIn').value=ep.p;\n\n  // 请求标题（端点名 + 描述）\n  $('#reqTitle').innerHTML='<span class=\"hicon\">'+(GROUPS[gi].icon)+'</span>'+esc(ep.name)+' <span class=\"desc\">'+esc(ep.desc||'')+'</span>';\n\n  // path 参数\n  const pw=$('#paramsWrap');\n  if(ep.params && ep.params.length){\n    pw.hidden=false; pw.innerHTML='';\n    ep.params.forEach(pp=>{\n      const lab=document.createElement('label');\n      lab.innerHTML='<span>{'+pp.k+'}</span>';\n      const inp=document.createElement('input'); inp.value=pp.v; inp.dataset.k=pp.k;\n      lab.appendChild(inp); pw.appendChild(lab);\n    });\n  } else pw.hidden=true;\n\n  // body\n  const bw=$('#bodyWrap');\n  if(ep.body!==undefined){\n    bw.hidden=false;\n    $('#bodyIn').value=JSON.stringify(ep.body,null,2);\n  } else bw.hidden=true;\n\n  // 快捷测试数据按钮组（仅写入类端点有预置用例时显示）\n  renderQTests(ep);\n\n  // 响应区：该端点（默认参数）有缓存则直接恢复，否则重置\n  let fp=ep.p;\n  if(ep.params) ep.params.forEach(pp=>{ fp=fp.split('{'+pp.k+'}').join(encodeURIComponent(pp.v)); });\n  const ck=cacheKeyOf(ep.m, base()+fp, ep.body!==undefined?JSON.stringify(ep.body):'');\n  const ent=cacheGet(ck);\n  if(ent && ent.r){\n    lastResp=ent.r;\n    respFmt=ent.f||'json';\n    document.querySelectorAll('#respFmt button').forEach(b=>b.classList.toggle('active', b.dataset.fmt===respFmt));\n    showResult(ent.r, '🕘 缓存结果 · '+ep.m+' '+ep.p, ent.t);\n  } else {\n    $('#statCard').hidden=true; $('#respCard').hidden=true; $('#stats').innerHTML=''; $('#respBody').innerHTML=''; $('#respMeta').innerHTML='';\n  }\n}\n\n/* ================= 快捷测试数据：渲染按钮 + 点击填充/发送 ================= */\nfunction renderQTests(ep){\n  const box=$('#quickTests'), list=$('#qtList');\n  if(!box || !list) return;\n  const key=ep.m+' '+ep.p;                 // 如 'POST /reports'、'PUT /reports/{id}'\n  const cases=QUICK_TESTS[key];\n  if(!cases || !cases.length){ box.hidden=true; list.innerHTML=''; return; }\n  box.hidden=false;\n  list.innerHTML='';\n  cases.forEach((tc,i)=>{\n    const b=document.createElement('button');\n    b.className='qt-btn'+(tc.edge?' qt-edge':'')+(tc.del?' qt-del':'');\n    b.textContent=tc.label;\n    b.title='用例 '+(i+1)+'/'+cases.length+'：'+tc.label+\n            (tc.body!==undefined?'\\n请求体: '+JSON.stringify(tc.body):'')+\n            (tc.params?'\\n参数: '+JSON.stringify(tc.params):'');\n    b.onclick=()=>applyQTest(tc);\n    list.appendChild(b);\n  });\n}\n\n/* 应用一个快捷测试用例：填 body / 填 params / （勾选时）自动发送 */\nfunction applyQTest(tc){\n  // 1) 填请求体\n  if(tc.body!==undefined && !$('#bodyWrap').hidden){\n    $('#bodyIn').value=JSON.stringify(tc.body,null,2);\n  }\n  // 2) 填路径参数（如 {id:5} → 找到 data-k=\"id\" 的输入框并赋值）\n  if(tc.params){\n    Object.entries(tc.params).forEach(([k,v])=>{\n      const inp=document.querySelector('#paramsWrap input[data-k=\"'+k+'\"]');\n      if(inp) inp.value=v;\n    });\n  }\n  // 3) 自动发送（默认勾选）\n  if($('#qtAutoSend') && $('#qtAutoSend').checked){\n    sendCurrent();\n  }\n}\n\n/* ================= 右侧卡片：本接口数据链路（点击菜单 → 白话说明） ================= */\nfunction renderChainCard(ep){\n  const card=$('#chainCard'); if(!card) return;\n  card.hidden=false;\n  const lk=ep.link||L.LOCAL;\n  const used=lk.nodes||[];\n  const on3=used.includes('base'), on4=used.includes('db');\n  const nodes=[\n    {t:'① 浏览器', d:ep.m+' '+ep.p, m:'同源 fetch，不直连数据库', on:true},\n    {t:'② 本工程端点', d:'FastAPI · 端口 5600', m:'router → service → db.py', on:true},\n    {t:'③ 基座 REST API', d:on3?lk.base:'—（不走）', m:on3?lk.apiNo+' · 远端服务器':'本次请求不经过基座', on:on3},\n    {t:'④ 目标数据', d:lk.target, m:lk.facade, on:on4},\n  ];\n  $('#chainFlow').innerHTML=nodes.map((n,i)=>\n    (i?'<div class=\"farrow\">→</div>':'')+\n    '<div class=\"fnode'+(n.on?'':' dim')+'\"><div class=\"fn-t\">'+esc(n.t)+'</div><div class=\"fn-d\">'+esc(n.d)+'</div><div class=\"fn-m\">'+esc(n.m)+'</div></div>'\n  ).join('');\n  const ex=EXPLAIN[ep.m+' '+ep.p]||ep.desc||'';\n  let txt='';\n  if(ex) txt+='<p><b>📌 这个接口做什么</b>　'+esc(ex)+'</p>';\n  if(lk.plain) txt+='<p><b>🔗 它走哪条链路</b>　'+esc(lk.plain)+'</p>';\n  $('#chainTxt').innerHTML=txt;\n  $('#chainEp').textContent=ep.name+' · '+lk.label;\n  $('#chainIO').innerHTML=\n    '<div class=\"col\"><div class=\"h\">📥 请求带什么</div><div class=\"plain\">'+esc(lk.inReq)+'</div></div>'+\n    '<div class=\"col\"><div class=\"h\">📦 返回什么</div><div class=\"plain\">'+esc(lk.out)+'</div></div>';\n  /* 折叠摘要：一句话概括链路 + 链路标签 */\n  const sumParts=[];\n  if(ex) sumParts.push(esc(ex.length>60?ex.slice(0,60)+'…':ex));\n  if(lk.label) sumParts.push('链路：'+esc(lk.label));\n  $('#chainSummary').textContent=sumParts.join('　·　');\n  /* 绑定折叠点击 */\n  if(!card._toggleBound){\n    $('#chainToggle').onclick=()=>card.classList.toggle('collapsed');\n    card._toggleBound=true;\n  }\n}\n\n/* ================= 构造最终请求 ================= */\nfunction buildReq(method, path, bodyText){\n  // 替换 {xxx} 参数\n  let finalPath=path;\n  if(current && current.params){\n    document.querySelectorAll('#paramsWrap input').forEach(inp=>{\n      finalPath=finalPath.split('{'+inp.dataset.k+'}').join(encodeURIComponent(inp.value));\n    });\n  }\n  let body=null;\n  if(method!=='GET' && method!=='DELETE' && bodyText && bodyText.trim()){\n    body=JSON.parse(bodyText);\n  }\n  const url=base()+finalPath;\n  return {method,url,body};\n}\n\nasync function doFetch(method,url,body){\n  const t0=performance.now();\n  const opts={method,headers:{'Content-Type':'application/json'}};\n  if(body!==null) opts.body=JSON.stringify(body);\n  let res, text='', ok=false, status=0;\n  try{\n    res=await fetch(url,opts);\n    status=res.status; ok=res.ok;\n    text=await res.text();\n  }catch(e){\n    return {elapsed:performance.now()-t0, status:0, ok:false, error:String(e), text:''};\n  }\n  const elapsed=performance.now()-t0;\n  let json=null; try{json=JSON.parse(text)}catch(e){}\n  return {elapsed,status,ok,text,json};\n}\n\nfunction speedClass(ms){ return ms<150?'fast':(ms<800?'mid':'slow'); }\nfunction statusClass(ok){ return ok?'ok':'err'; }\n\nfunction showResult(r, label, cachedAt){\n  $('#statCard').hidden=false; $('#respCard').hidden=false;\n  // 统计（单请求或压测）\n  const times=r.times||[r.elapsed];\n  const sorted=[...times].sort((a,b)=>a-b);\n  const avg=times.reduce((a,b)=>a+b,0)/times.length;\n  const p95=sorted[Math.min(sorted.length-1,Math.ceil(sorted.length*0.95)-1)]||sorted[sorted.length-1];\n  const st=statusClass(r.ok);\n  $('#stats').innerHTML=\n    '<div class=\"stat '+st+(r.ok?' ok':' err')+'\"><div class=\"v\">'+(r.ok?'成功':'失败')+'</div><div class=\"l\">HTTP '+r.status+'</div></div>'+\n    '<div class=\"stat '+speedClass(avg)+'\"><div class=\"v\">'+avg.toFixed(0)+'<small> ms</small></div><div class=\"l\">平均耗时</div></div>'+\n    '<div class=\"stat\"><div class=\"v\">'+sorted[0].toFixed(0)+'<small> ms</small></div><div class=\"l\">最快 min</div></div>'+\n    '<div class=\"stat\"><div class=\"v\">'+p95.toFixed(0)+'<small> ms</small></div><div class=\"l\">P95</div></div>'+\n    '<div class=\"stat\"><div class=\"v\">'+sorted[sorted.length-1].toFixed(0)+'<small> ms</small></div><div class=\"l\">最慢 max</div></div>'+\n    (times.length>1?'<div class=\"stat\"><div class=\"v\">'+times.length+'</div><div class=\"l\">压测次数</div></div>':'')+\n    '<div class=\"stat\"><div class=\"v\">'+((r.bytes!=null?r.bytes:(r.text?new Blob([r.text]).size:0))/1024).toFixed(1)+'<small> KB</small>'+'</div><div class=\"l\">响应体大小</div></div>';\n\n  $('#respMeta').innerHTML='<span>⏱ 平均 '+avg.toFixed(1)+' ms</span><span>HTTP '+r.status+'</span><span>'+esc(label||'')+'</span>'+(cachedAt?cacheBadgeHtml(cachedAt):'');\n  lastResp = r;\n  renderRespBody();\n}\n\n/* ================= 响应输出格式：JSON / 层级 / 表格 ================= */\nfunction renderRespBody(){\n  const rb=$('#respBody');\n  if(!lastResp){ rb.innerHTML=''; return; }\n  const r=lastResp;\n  if(!r.ok && r.error){\n    rb.innerHTML='<div class=\"err-box\">网络错误: '+esc(r.error)+'\\n\\n请确认服务已启动、API 基地址正确（同源相对地址，或 http://127.0.0.1:5600/api）。</div>';\n    return;\n  }\n  if(respFmt==='json'){\n    rb.innerHTML = (r.json!==null) ? '<div class=\"code\">'+hlJSON(r.json)+'</div>'\n                                    : '<div class=\"code\">'+(esc(r.text)||'(空响应)')+'</div>';\n    return;\n  }\n  if(r.json===null){\n    rb.innerHTML='<div class=\"hint\">该响应不是 JSON，仅提供原文。</div><div class=\"code\">'+(esc(r.text)||'(空响应)')+'</div>';\n    return;\n  }\n  rb.innerHTML = respFmt==='tree' ? treeHTML(r.json) : tableHTML(r.json);\n}\n\n/* ---- 层级树 ---- */\nfunction valSpan(v){\n  if(v===null) return '<span class=\"t-null\">null</span>';\n  const t=typeof v;\n  if(t==='string'){\n    const trunc = v.length>120;\n    const s = trunc ? v.substring(0,120) : v;\n    return '<span class=\"t-s\"'+(trunc?' title=\"'+esc(v)+'\"':'')+'>\"'+esc(s)+(trunc?'<span class=\"t-null\"> …</span>':'')+'\"</span>';\n  }\n  if(t==='number') return '<span class=\"t-n\">'+v+'</span>';\n  if(t==='boolean') return '<span class=\"t-b\">'+v+'</span>';\n  return '<span>'+esc(String(v))+'</span>';\n}\nfunction nodeHTML(key, val, isArrIdx, depth){\n  const k = (key===null)\n    ? '<span class=\"t-null\">(root)</span>'\n    : '<span class=\"t-k\">'+esc(String(key))+'</span><span class=\"t-null\">'+(isArrIdx?' ':' : ')+'</span>';\n  if(val!==null && typeof val==='object'){\n    const isArr=Array.isArray(val);\n    const entries=isArr?val:Object.entries(val);\n    const open=depth<2;   // 默认展开前两层\n    let inner='';\n    entries.forEach((x,i)=>{\n      inner += isArr ? nodeHTML(i, x, true, depth+1)\n                     : nodeHTML(x[0], x[1], false, depth+1);\n    });\n    return '<div class=\"tnode\"><div class=\"trow tparent\"><span class=\"tcaret\">'+(open?'▾':'▸')+'</span>'+k\n      +'<span class=\"t-typ '+(isArr?'arr':'obj')+'\">'+(isArr?'[Array':'{Object')+' '+entries.length+(isArr?']':'}')+'</span></div>'\n      +'<div class=\"tchild\"'+(open?'':' hidden')+'>'+inner+'</div></div>';\n  }\n  return '<div class=\"trow\">'+k+valSpan(val)+'</div>';\n}\nfunction treeHTML(v){ return '<div class=\"troot\">'+nodeHTML(null,v,false,0)+'</div>'; }\n\n/* ---- 表格（自动找数组：data.rows / data / rows / 顶层数组）---- */\nfunction findRows(j){\n  if(Array.isArray(j)) return j;\n  if(j && typeof j==='object'){\n    if(j.data && typeof j.data==='object' && !Array.isArray(j.data) && Array.isArray(j.data.rows)) return j.data.rows;\n    if(Array.isArray(j.data)) return j.data;\n    if(Array.isArray(j.rows)) return j.rows;\n  }\n  return null;\n}\nfunction cellVal(v){\n  if(v===null||v===undefined) return '∅';\n  if(typeof v==='object') return JSON.stringify(v);\n  return String(v);\n}\nfunction tableHTML(j){\n  const rows=findRows(j);\n  if(!rows || rows.length===0 || typeof rows[0]!=='object'){\n    return '<div class=\"hint\">未在该响应中检测到表格数据（对象数组），请切到「JSON / 层级」查看。</div>';\n  }\n  const cols=Object.keys(rows[0]);\n  let html='<div class=\"hint\" style=\"margin:0 0 8px\">'+rows.length+' 行 × '+cols.length+' 列（嵌套对象/数组已展开为 JSON 字符串）</div>';\n  html+='<div class=\"dtable-wrap\"><table class=\"dtable\"><thead><tr>'\n    +cols.map(c=>'<th title=\"'+esc(c)+'\">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'\n    +rows.map(r=>'<tr>'+cols.map(c=>'<td title=\"'+esc(cellVal(r[c]))+'\">'+esc(cellVal(r[c]))+'</td>').join('')+'</tr>').join('')\n    +'</tbody></table></div>';\n  return html;\n}\n\n/* ---- 格式切换 & 层级树展开/收起 ---- */\n$('#respFmt').addEventListener('click', e=>{\n  const btn=e.target.closest('button[data-fmt]');\n  if(!btn || btn.dataset.fmt===respFmt) return;\n  respFmt=btn.dataset.fmt;\n  document.querySelectorAll('#respFmt button').forEach(b=>b.classList.toggle('active', b===btn));\n  renderRespBody();\n});\n$('#respBody').addEventListener('click', e=>{\n  const p=e.target.closest('.tparent');\n  if(!p) return;\n  const c=p.nextElementSibling;\n  if(!c || !c.classList.contains('tchild')) return;\n  c.hidden=!c.hidden;\n  p.querySelector('.tcaret').textContent=c.hidden?'▸':'▾';\n});\n\n/* ================= 发送 / 压测 ================= */\nasync function sendCurrent(){\n  const method=$('#methodSel').value;\n  let bodyText=$('#bodyWrap').hidden?'':$('#bodyIn').value;\n  let req; try{ req=buildReq(method,$('#pathIn').value,bodyText);}catch(e){dlgAlert({title:'JSON 格式错误',message:'请求体不是合法 JSON：'+e});return;}\n  $('#sendBtn').disabled=true;\n  const r=await doFetch(req.method,req.url,req.body);\n  cacheSave(cacheKeyOf(req.method,req.url,bodyText), r);\n  showResult(r, req.method+' '+req.url);\n  $('#sendBtn').disabled=false;\n}\n$('#sendBtn').onclick=sendCurrent;\n\n$('#respMeta').addEventListener('click', e=>{\n  if(e.target.closest('.cache-re')) sendCurrent();   // 缓存徽标上的\"重新查询\"\n});\n\n$('#loadBtn').onclick=async()=>{\n  const method=$('#methodSel').value;\n  let bodyText=$('#bodyWrap').hidden?'':$('#bodyIn').value;\n  let req; try{ req=buildReq(method,$('#pathIn').value,bodyText);}catch(e){dlgAlert({title:'JSON 格式错误',message:'请求体不是合法 JSON：'+e});return;}\n  const n=Math.max(1,Math.min(50,parseInt($('#loadN').value)||5));\n  $('#loadBtn').disabled=true; $('#loadBtn').textContent='压测中…';\n  const results=await Promise.all(Array.from({length:n},()=>doFetch(req.method,req.url,req.body)));\n  const last=results[results.length-1];\n  const times=results.map(r=>r.elapsed);\n  showResult({...last,times}, req.method+' '+req.url+' ×'+n);\n  $('#loadBtn').disabled=false; $('#loadBtn').textContent='压测';\n};\n\n$('#fmtBody').onclick=()=>{\n  try{ $('#bodyIn').value=JSON.stringify(JSON.parse($('#bodyIn').value),null,2);}catch(e){dlgAlert({title:'JSON 格式错误',message:'JSON 非法：'+e});}\n};\n\n$('#copyCurl').onclick=()=>{\n  const method=$('#methodSel').value;\n  let bodyText=$('#bodyWrap').hidden?'':$('#bodyIn').value;\n  let req; try{ req=buildReq(method,$('#pathIn').value,bodyText);}catch(e){dlgAlert({title:'JSON 格式错误',message:'请求体不是合法 JSON：'+e});return;}\n  let curl='curl -X '+method+' \"'+req.url+'\" -H \"Content-Type: application/json\"';\n  if(req.body!==null) curl+=' -d '+JSON.stringify(req.body);\n  navigator.clipboard&&navigator.clipboard.writeText(curl).then(()=>{const b=$('#copyCurl');const t=b.textContent;b.textContent='已复制 ✓';setTimeout(()=>b.textContent=t,1200);});\n};\n\n/* 自由请求 */\n$('#fSend').onclick=async()=>{\n  const method=$('#fMethod').value, path=$('#fPath').value, bt=$('#fBody').value;\n  let body=null; if(method!=='GET'&&method!=='DELETE'&&bt.trim()){ try{body=JSON.parse(bt);}catch(e){dlgAlert({title:'JSON 格式错误',message:'JSON 非法：'+e});return;} }\n  const r=await doFetch(method,base()+path,body);\n  showResult(r, method+' '+path);\n};\n\n/* 健康检测 */\nasync function checkHealth(){\n  const dot=$('#hDot'),txt=$('#hText');\n  dot.className='dot busy'; txt.textContent='检测中…';\n  try{\n    const r=await fetch(base()+'/healthz');\n    const j=await r.json();\n    const ok=j.code===0 && j.data && j.data.base_api==='ok';\n    dot.className='dot '+(ok?'ok':'fail');\n    txt.textContent=ok?'基座 API 连通':'基座 API 不可达';\n  }catch(e){ dot.className='dot fail'; txt.textContent='后端未启动 / 地址错误'; }\n}\n\n/* ================= 可搜索下拉 combobox（源表选择 / 落地表切换共用） ================= */\nfunction makeCombobox(host, cfg){\n  cfg = cfg || {};\n  host.classList.add('cbx');\n  host.innerHTML =\n    '<input type=\"text\" spellcheck=\"false\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"false\" '+\n    'placeholder=\"'+esc(cfg.placeholder||'')+'\" title=\"'+esc(cfg.title||'')+'\">'+\n    '<span class=\"carrow\">▾</span><ul class=\"cl\" role=\"listbox\"></ul>';\n  const inp = host.querySelector('input'), list = host.querySelector('.cl');\n  let sel = -1, open_ = false, cur = '';\n\n  function open(){\n    sel = -1;\n    let kw = inp.value.trim().toLowerCase();\n    if(kw === cur.toLowerCase()) kw = '';   // 输入框还停留在当前选中值时不过滤，展示全列表\n    const opts=(cfg.options||[]).filter(o=>!kw || (o.value+' '+(o.desc||'')+' '+(o.kw||'')).toLowerCase().includes(kw));\n    list.innerHTML = opts.length\n      ? opts.map(o=>\n          '<li data-v=\"'+esc(o.value)+'\" class=\"'+(o.value===cur?'cur':'')+(o.dim?' dim':'')+'\" title=\"'+esc(o.label||o.value)+'\">'+\n          esc(o.value)+(o.tags||'')+(o.desc?'<span class=\"cd\">'+esc(o.desc)+'</span>':'')+'</li>').join('')\n      : '<li class=\"nm\">无匹配（可直接输入）</li>';\n    host.classList.add('open'); inp.setAttribute('aria-expanded','true');\n    open_ = true;\n  }\n  function close(){\n    host.classList.remove('open'); inp.setAttribute('aria-expanded','false');\n    open_ = false; sel = -1;\n  }\n  function pick(v){\n    const o=(cfg.options||[]).find(x=>x.value===v); if(!o) return;\n    inp.value = o.value; cur = o.value; close();\n    if(cfg.onChange) cfg.onChange(o.value);\n  }\n  inp.addEventListener('focus', ()=>open());\n  inp.addEventListener('click', ()=>open());\n  inp.addEventListener('input', ()=>{ cur=''; open(); });\n  inp.addEventListener('keydown', e=>{\n    if(e.key==='ArrowDown' || e.key==='ArrowUp'){\n      e.preventDefault();\n      const items=[...list.querySelectorAll('li[data-v]')];\n      if(!items.length) return;\n      if(!open_) open();\n      const n=items.length;\n      let i = items.findIndex(li=>li.classList.contains('act'));\n      i = e.key==='ArrowDown' ? (i+1)%n : (i<=0 ? n-1 : i-1);\n      items.forEach(li=>li.classList.remove('act'));\n      items[i].classList.add('act'); items[i].scrollIntoView({block:'nearest'});\n      sel = items[i].dataset.v;\n    }else if(e.key==='Enter'){\n      if(open_){ e.preventDefault(); inp.dataset.pendingEnter='1'; close(); }\n      else if(cfg.onEnter) cfg.onEnter();\n    }else if(e.key==='Escape'){\n      close();\n    }\n  });\n  inp.addEventListener('keyup', e=>{\n    if(e.key!=='Enter') return;\n    if(inp.dataset.pendingEnter){\n      delete inp.dataset.pendingEnter;\n      if(cfg.onEnter) cfg.onEnter();\n    } else if(open_ && sel) pick(sel);\n  });\n  list.addEventListener('mousedown', e=>{\n    const li=e.target.closest('li[data-v]'); if(!li) return;\n    e.preventDefault();\n    pick(li.dataset.v);\n  });\n  document.addEventListener('click', e=>{ if(!host.contains(e.target)) close(); });\n  return {\n    host, input:inp,\n    setOptions(o){ cfg.options=o; },\n    value(){ return inp.value.trim(); },\n    set(v){ inp.value=v||''; cur=v||''; },\n    clear(){ inp.value=''; cur=''; },\n  };\n}\n\n/* 多选下拉（「只显示这些列」用）：chip 展示已选 + 搜索过滤 + 全选/反选/清空 + 按表 localStorage 记忆 */\nfunction makeMultiSelect(host, cfg){\n  cfg = cfg || {};\n  host.classList.add('msel');\n  host.innerHTML =\n    '<div class=\"msel-box\" title=\"'+esc(cfg.title||'')+'\"></div>'+\n    '<span class=\"carrow\">▾</span>'+\n    '<div class=\"msel-list\"><div class=\"msel-bar\"></div><ul class=\"msel-ll\"></ul></div>';\n  const box=host.querySelector('.msel-box'), bar=host.querySelector('.msel-bar'), list=host.querySelector('.msel-ll');\n  const inp=document.createElement('input');\n  inp.type='text'; inp.spellcheck=false; inp.autocomplete='off';\n  inp.placeholder=cfg.placeholder||'';\n  box.appendChild(inp);\n  let opts=[], sel=new Set(), open_=false, storeKey='';\n\n  function storeOf(){ return cfg.storagePrefix+'_'+storeKey; }\n  function save(){ if(!storeKey) return; try{ localStorage.setItem(storeOf(), JSON.stringify([...sel])); }catch(e){} }\n  /* 仅用户主动变更（勾选/chip 删/全选/反选/清空/回车添加）时触发；setOptions/set/clear 程序化恢复不触发 */\n  function emit(){ if(cfg.onChange){ try{ cfg.onChange([...sel].sort()); }catch(e){} } }\n  function visible(){\n    const kw=inp.value.trim().toLowerCase();\n    return opts.filter(o=>!kw || String(o.value).toLowerCase().includes(kw));\n  }\n  function renderList(){\n    const vis=visible();\n    bar.innerHTML='<span class=\"msel-cnt\">'+sel.size+' / '+opts.length+' 列已选'\n      +(inp.value.trim()?' · 过滤 “'+esc(inp.value.trim())+'”（全选/反选只作用于过滤结果）':'')+'</span>'\n      +'<button type=\"button\" data-act=\"all\" title=\"选中当前列表全部（有搜索词时仅全选搜索结果）\">全选</button>'\n      +'<button type=\"button\" data-act=\"inv\" title=\"反转当前列表中各列的选中状态\">反选</button>'\n      +'<button type=\"button\" data-act=\"clr\" title=\"清空全部已选\">清空</button>';\n    list.classList.toggle('two', opts.length>=40);\n    list.innerHTML = vis.length\n      ? vis.map(o=>'<li data-v=\"'+esc(o.value)+'\" class=\"'+(sel.has(o.value)?'on':'')+'\"><span class=\"ck\">✓</span>'+esc(o.value)+'</li>').join('')\n      : '<li class=\"nm\">无匹配列'+(opts.length?'（请修改搜索词）':' —— 查询成功后自动填充当前表列名')+'</li>';\n    bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{\n      const a=b.dataset.act;\n      if(a==='all') vis.forEach(o=>sel.add(o.value));\n      else if(a==='inv') vis.forEach(o=>{ if(sel.has(o.value)) sel.delete(o.value); else sel.add(o.value); });\n      else sel.clear();\n      save(); renderChips(); renderList(); emit();\n    });\n    list.querySelectorAll('li[data-v]').forEach(li=>li.onmousedown=e=>{ e.preventDefault(); toggle(li.dataset.v); });\n  }\n  function renderChips(){\n    box.querySelectorAll('.chip').forEach(c=>c.remove());\n    [...sel].sort().forEach(v=>{\n      const c=document.createElement('span'); c.className='chip';\n      c.innerHTML=esc(v)+'<button type=\"button\" data-x=\"'+esc(v)+'\" title=\"移除该列\">×</button>';\n      box.insertBefore(c,inp);\n    });\n    box.querySelectorAll('.chip button').forEach(b=>b.onclick=e=>{ e.stopPropagation(); toggle(b.dataset.x); });\n    inp.placeholder = sel.size? '搜索列名（回车精确添加）' : (cfg.placeholder||'');\n  }\n  function toggle(v){ if(sel.has(v)) sel.delete(v); else sel.add(v); save(); renderChips(); renderList(); emit(); }\n  function open(){ if(open_) return; open_=true; host.classList.add('open'); inp.value=''; renderList(); }\n  function close(){ open_=false; host.classList.remove('open'); }\n  inp.addEventListener('focus',open);\n  inp.addEventListener('click',open);\n  inp.addEventListener('input',()=>{ if(!open_) open(); else renderList(); });\n  inp.addEventListener('keydown',e=>{\n    if(e.key==='Enter'){\n      const kw=inp.value.trim().toLowerCase();\n      const m=kw?opts.filter(o=>o.value.toLowerCase()===kw):[];\n      if(m.length===1){ toggle(m[0].value); inp.value=''; renderList(); }\n      else close();\n    } else if(e.key==='Escape') close();\n  });\n  document.addEventListener('click',e=>{ if(!e.composedPath().includes(host)) close(); });\n  return {\n    host, input:inp,\n    /* tblKey：按表记忆的存储键；切换表时恢复该表上次保存的选择 */\n    setOptions(o, tblKey){\n      opts=(o||[]).map(x=>typeof x==='string'?{value:x}:x);\n      storeKey=tblKey||'';\n      sel=new Set();\n      if(storeKey){\n        try{\n          const raw=localStorage.getItem(storeOf());\n          if(raw){ const arr=JSON.parse(raw); if(Array.isArray(arr)) sel=new Set(arr.filter(v=>opts.some(o=>o.value===v))); }\n        }catch(e){}\n      }\n      renderChips(); if(open_) renderList();\n    },\n    value(){ return [...sel].sort().join(','); },\n    set(v){ sel=new Set(String(v||'').split(',').map(s=>s.trim()).filter(Boolean)); save(); renderChips(); if(open_) renderList(); },\n    clear(){ sel.clear(); save(); renderChips(); if(open_) renderList(); },\n  };\n}\n\n/* ================= 源表直查 ================= */\n/* 目标表列集合缓存：小写表名 -> Set(小写列名)。来源：/data/columns 接口。\n   两级缓存：① 内存 SRC_COLS（本次会话快查）；② localStorage api_test_src_cols_v1（跨会话按表持久化记忆）。\n   下次再查同表：先用缓存快速展示下拉，同时后台异步拉最新列名与缓存比对，有变化则更新下拉与缓存。 */\nconst SRC_COLS={};\nfunction colBase(t){ return String(t||'').toLowerCase().split('.').pop(); }\n/* ---- 列名按表持久化记忆（localStorage） ---- */\nconst SRC_COLS_STORE_KEY='api_test_src_cols_v1';\nfunction loadColsStore(){ try{ const o=JSON.parse(localStorage.getItem(SRC_COLS_STORE_KEY)||'{}'); return o&&typeof o==='object'?o:{}; }catch(e){ return {}; } }\nfunction saveColsStore(o){\n  try{\n    const keys=Object.keys(o);\n    if(keys.length>200){   // 上限 200 张表，超过按 ts 最旧删除\n      keys.sort((a,b)=>(o[a].ts||0)-(o[b].ts||0));\n      while(Object.keys(o).length>200) delete o[keys.shift()];\n    }\n    localStorage.setItem(SRC_COLS_STORE_KEY, JSON.stringify(o));\n  }catch(e){/* localStorage 满或禁用，忽略 */}\n}\nfunction colsStoreGet(b){ const o=loadColsStore(); const e=o[b]; return (e&&Array.isArray(e.cols)&&e.cols.length)?e.cols:null; }\nfunction colsStoreSet(b, cols){\n  if(!b||!Array.isArray(cols)||!cols.length) return;\n  const o=loadColsStore(); o[b]={cols:cols.slice(), ts:Date.now()}; saveColsStore(o);\n}\nasync function fetchColsByApi(tbl, opts){\n  const b=colBase(tbl); if(!b) return null;\n  const fresh=!!(opts&&opts.fresh);\n  if(!fresh && SRC_COLS[b]) return SRC_COLS[b];   // ① 内存命中\n  if(!fresh){   // ② 内存没有 → localStorage 持久化记忆\n    const cached=colsStoreGet(b);\n    if(cached){ SRC_COLS[b]=new Set(cached.map(c=>String(c).toLowerCase())); }\n  }\n  try{\n    const r=await fetch(base()+'/data/columns/'+encodeURIComponent(b)+'?source_db=netcare');\n    const j=await r.json();\n    if(j.code===0 && Array.isArray(j.data) && j.data.length){\n      const cols=j.data.map(c=>String(c.field).toLowerCase());\n      SRC_COLS[b]=new Set(cols);\n      colsStoreSet(b, cols);   // 写入持久化记忆\n      return SRC_COLS[b];\n    }\n  }catch(e){/* 取列失败不阻塞查询，退回不校验 */}\n  return SRC_COLS[b]||null;\n}\n/* 后台刷新比对：异步拉最新列名，与缓存不同则更新内存+localStorage，并刷新当前下拉（若正在显示该表）。\n   —— 满足\"下次再查询该表还会进行刷新和比对，方便更新表列名下拉\"。 */\nlet srcColsBgTimer=null;\nfunction bgRefreshCols(tbl){\n  const b=colBase(tbl); if(!b) return;\n  clearTimeout(srcColsBgTimer);\n  srcColsBgTimer=setTimeout(async ()=>{\n    const before=SRC_COLS[b]?new Set(SRC_COLS[b]):null;\n    const after=await fetchColsByApi(b, {fresh:true});\n    if(!after) return;\n    const changed=!before || before.size!==after.size || [...after].some(c=>!before.has(c));\n    if(!changed) return;\n    // 列名有变化 → 若当前正在显示该表，刷新下拉选项\n    const cur=(srcCurTable&&colBase(srcCurTable))||(srcLastInput&&colBase(srcLastInput));\n    if(cur===b){\n      SRC_CUR_COLS=after;\n      SRC_COL_OPTS=[...after].sort().map(c=>({value:c}));\n      srcColsCbx.setOptions(SRC_COL_OPTS, b);\n    }\n  }, 200);   // 200ms 去抖，避免连续查询触发多次\n}\nasync function resolveCols(name){\n  /* 取实际要查的目标表列集合（输入源表名时经 lookup 解析到落地表）。取不到返回 null（不校验）。 */\n  let s=await fetchColsByApi(name);\n  if(s) return s;\n  try{\n    const r=await fetch(base()+'/data/table-map/lookup?name='+encodeURIComponent(name));\n    const j=await r.json();\n    if(j.code===0 && j.data && j.data.resolved_table){\n      s=await fetchColsByApi(j.data.resolved_table);\n      if(s) SRC_COLS[colBase(name)]=s;  // 源表名固定解析到第一张落地表，可复用\n    }\n  }catch(e){/* ignore */}\n  return s||null;\n}\nasync function resolveTargetBase(name){\n  /* 查询目标表的归一表名（源表名解析到第一张落地表），取不到返回 null */\n  if(await fetchColsByApi(name)) return colBase(name);\n  try{\n    const r=await fetch(base()+'/data/table-map/lookup?name='+encodeURIComponent(name));\n    const j=await r.json();\n    if(j.code===0 && j.data && j.data.resolved_table) return colBase(j.data.resolved_table);\n  }catch(e){/* ignore */}\n  return null;\n}\n\n/* 当前目标表的列（列名下拉选项用，查询成功后刷新；所有列名 combobox 共用这一个数组） */\nlet SRC_CUR_COLS=null, SRC_COL_OPTS=[];\nasync function refreshSrcColOptions(tbl){\n  const s=tbl?await fetchColsByApi(tbl):null;\n  if(s){\n    SRC_CUR_COLS=s;\n    SRC_COL_OPTS=[...s].sort().map(c=>({value:c}));\n    srcColsCbx.setOptions(SRC_COL_OPTS, colBase(tbl));   // 填充当前表全部列，并恢复该表 localStorage 记忆的选择\n  }\n  if(tbl) bgRefreshCols(tbl);   // 后台异步拉最新列名与缓存比对，有变化则更新下拉（不 await，不阻塞）\n}\n\nfunction addSrcFlt(){\n  const d=document.createElement('div'); d.className='fltr';\n  d.innerHTML='<div class=\"cbx fcolbox\" title=\"下拉选择列，也可手动输入（选项为当前目标表的字段）\"></div>'+\n    '<select class=\"fop\">'+['=','!=','>','<','>=','<=','like','not like','in'].map(o=>'<option>'+o+'</option>').join('')+'</select>'+\n    '<input class=\"fval\" placeholder=\"值（IN 逗号分隔，LIKE 可带 %）\" spellcheck=\"false\">'+\n    '<button type=\"button\" class=\"fx\" title=\"删除该条件\">×</button>';\n  d.querySelector('.fx').onclick=()=>d.remove();\n  makeCombobox(d.querySelector('.fcolbox'),{\n    placeholder:'列名', title:'下拉选择列，也可手动输入（选项为当前目标表的字段）',\n    options:SRC_COL_OPTS,\n  });\n  $('#srcFltWrap').appendChild(d);\n}\n$('#srcAddFlt').onclick=addSrcFlt;\n\n/* ================= 自定义查询（源表直查快照：表/行数/过滤条件/显示列/落地表 全量保存，localStorage 持久化） ================= */\nconst CUSTOM_KEY='api_test_custom_q';\nlet curCustom=null;   // 当前正在执行的自定义查询快照\nfunction customList(){ try{ const a=JSON.parse(localStorage.getItem(CUSTOM_KEY)||'[]'); return Array.isArray(a)?a:[]; }catch(e){ return []; } }\nfunction saveCustomList(a){ try{ localStorage.setItem(CUSTOM_KEY, JSON.stringify(a)); }catch(e){} }\nfunction readFlts(){\n  const a=[];\n  document.querySelectorAll('#srcFltWrap .fltr').forEach(d=>{\n    a.push({c:d.querySelector('.fcolbox input').value.trim(), o:d.querySelector('.fop').value, v:d.querySelector('.fval').value.trim()});\n  });\n  return a;\n}\nfunction setFlts(arr){\n  const w=$('#srcFltWrap'); w.innerHTML='';\n  (arr||[]).forEach(f=>{\n    if(!f.c && !f.v) return;\n    addSrcFlt();\n    const d=w.lastElementChild;\n    d.querySelector('.fcolbox input').value=f.c||'';\n    d.querySelector('.fop').value=f.o||'=';\n    d.querySelector('.fval').value=f.v||'';\n  });\n}\nfunction renderCustomGroup(){\n  CUSTOM_GROUP.eps=customList().map(s=>{\n    const n=s.flts.filter(f=>f.c&&f.v).length;\n    return { m:'★', p:s.name, name:s.name,\n      desc:'表 '+s.t+(n?' · '+n+' 个条件':'')+(s.cols?' · 自定义列':''),\n      kind:'custom', cid:s.id, link:L.LOCAL };\n  });\n  if(window.__syncLeftRail) window.__syncLeftRail();\n}\n$('#srcSaveBtn').onclick=async function(){\n  const t=(srcCb.value()||'').trim();\n  if(!t){ await dlgAlert({title:'尚未选择表', message:'请先在左侧表名下拉输入要保存的表名，再点「保存为自定义」。'}); return; }\n  const flts=readFlts(), cols=srcColsCbx.value();\n  const info='表：'+t+'\\n行数：'+($('#srcLimit').selectedOptions[0]?$('#srcLimit').selectedOptions[0].text:$('#srcLimit').value)\n    +(flts.filter(f=>f.c&&f.v).length?'\\n过滤条件：'+flts.filter(f=>f.c&&f.v).map(f=>f.c+' '+f.o+' '+f.v).join('；'):'')\n    +(cols?'\\n显示列：'+cols+'（自定义）':'\\n显示列：全部列')\n    +(srcCurTable && srcCurTable!==colBase(t)?'\\n落地表：'+srcCurTable:'');\n  const nm=await dlgPrompt({\n    title:'保存为自定义查询',\n    message:info+(curCustom?'\\n\\n当前正在执行「'+curCustom.name+'」：保持原名称 = 覆盖它；改个名字 = 另存为新的。':'\\n\\n请输入左侧菜单显示的名称：'),\n    value:curCustom?curCustom.name:t,\n    placeholder:'菜单名称（如：BG问题速览）',\n  });\n  if(nm===null) return;\n  const name=nm.trim(); if(!name) return;\n  const arr=customList();\n  const dup=arr.find(x=>x.name===name);   // 必须取 arr 内实例：curCustom 是另一份 localStorage 解析副本，改它不会随 saveCustomList(arr) 持久化\n  if(dup){\n    const ov=await dlgConfirm({\n      title:'已存在同名自定义查询',\n      message:'「'+name+'」已存在。\\n\\n覆盖 = 用当前条件更新它（保留原位置）\\n另存为 = 原条目保留，新建一条',\n      okText:'覆盖', cancelText:'另存为', danger:true,\n    });\n    if(ov){\n      Object.assign(dup, { ts:Date.now(), t:t, limit:$('#srcLimit').value, flts:flts, cols:cols, land:srcCurTable||'' });\n      if(curCustom&&dup.id===curCustom.id) curCustom=dup;\n      saveCustomList(arr);\n      renderCustomGroup(); renderLeft();\n      const g=[...document.querySelectorAll('.grp')].find(x=>x.dataset.g===String(GROUPS.indexOf(CUSTOM_GROUP)));\n      if(g) g.classList.remove('closed');\n      const tip=$('#srcCustomTip');\n      tip.hidden=false; tip.innerHTML='✅ 已覆盖自定义查询「<b>'+esc(name)+'</b>」';\n      clearTimeout(tip._t); tip._t=setTimeout(()=>{ tip.hidden=true; },4000);\n      toast('✅ 已覆盖「'+esc(name)+'」：过滤条件 / 行数 / 显示列已原地更新');\n      return;\n    }\n    const nn=await dlgPrompt({title:'另存为新的自定义查询', message:'原「'+name+'」保留，请输入新名称：', value:name+'-新'});\n    if(nn===null) return;\n    const nname=nn.trim(); if(!nname) return;\n    arr.unshift({ id:'c'+Date.now().toString(36)+Math.random().toString(36).slice(2,6), name:nname, ts:Date.now(),\n      t:t, limit:$('#srcLimit').value, flts:flts, cols:cols, land:srcCurTable||'' });\n    saveCustomList(arr);\n    renderCustomGroup(); renderLeft();\n    const g=[...document.querySelectorAll('.grp')].find(x=>x.dataset.g===String(GROUPS.indexOf(CUSTOM_GROUP)));\n    if(g) g.classList.remove('closed');\n    const tip=$('#srcCustomTip');\n    tip.hidden=false; tip.innerHTML='✅ 已另存为自定义查询「<b>'+esc(nname)+'</b>」（左侧 ⭐ 自定义查询 菜单）';\n    clearTimeout(tip._t); tip._t=setTimeout(()=>{ tip.hidden=true; },4000);\n    toast('✅ 已另存为「'+esc(nname)+'」：原条目保留，新条目已创建');\n    return;\n  }\n  arr.unshift({ id:'c'+Date.now().toString(36)+Math.random().toString(36).slice(2,6), name:name, ts:Date.now(),\n    t:t, limit:$('#srcLimit').value, flts:flts, cols:cols, land:srcCurTable||'' });\n  saveCustomList(arr);\n  renderCustomGroup(); renderLeft();\n  const g=[...document.querySelectorAll('.grp')].find(x=>x.dataset.g===String(GROUPS.indexOf(CUSTOM_GROUP)));\n  if(g) g.classList.remove('closed');\n  const tip=$('#srcCustomTip');\n  tip.hidden=false; tip.innerHTML='✅ 已保存自定义查询「<b>'+esc(name)+'</b>」（左侧 ⭐ 自定义查询 菜单）';\n  clearTimeout(tip._t); tip._t=setTimeout(()=>{ tip.hidden=true; },4000);\n  toast('✅ 已保存「'+esc(name)+'」到左侧 ⭐ 自定义查询');\n};\nasync function applyCustomQuery(id){\n  const s=customList().find(x=>x.id===id);\n  const tip=$('#srcCustomTip');\n  if(!s){ if(tip) tip.hidden=true; return; }\n  curCustom=s;\n  srcCb.set(s.t); srcLastInput=s.t;\n  $('#srcLimit').value=(s.limit&&s.limit!=='')?s.limit:'100';\n  setFlts(s.flts);\n  const qname=s.land||s.t;\n  // 显示列：写入该表按表记忆，srcQuery 恢复选项时即按快照列生效（与手动选择同机制）\n  try{\n    if(s.cols){\n      const tb=await resolveTargetBase(qname);\n      if(tb) localStorage.setItem('api_test_src_cols_'+tb, JSON.stringify(s.cols.split(',').map(x=>x.trim()).filter(Boolean)));\n    }\n  }catch(e){/* 恢复列失败不阻塞查询 */}\n  tip.hidden=false;\n  tip.innerHTML='📌 正在执行自定义查询「<b>'+esc(s.name)+'</b>」（'+esc(s.t)+(s.land&&s.land!==colBase(s.t)?' → '+esc(s.land):'')+'）<button type=\"button\" class=\"btn btn-ghost\" style=\"padding:1px 8px;margin-left:8px\" data-delcustom=\"'+s.id+'\">🗑 删除此快捷方式</button>';\n  tip.querySelector('[data-delcustom]').onclick=()=>{\n    const a=customList().filter(x=>x.id!==s.id); saveCustomList(a);\n    curCustom=null; tip.hidden=true;\n    renderCustomGroup(); renderLeft();\n  };\n  if(s.land) srcQuery(s.land); else srcQuery();\n}\n\n/* 「只显示这些列」→ 多选下拉：选项 = 当前目标表全部列（查询成功后自动填充）；支持搜索 / 全选 / 反选 / 清空；选择按表记忆到 localStorage（api_test_src_cols_{表名}） */\nlet srcColsAutoTimer=null;\nconst srcColsCbx=makeMultiSelect($('#srcCols'),{\n  placeholder:'只显示这些列（点开展开多选，留空 = 全部列）',\n  title:'点开为多选列表：支持列名搜索、全选 / 反选 / 清空，chip 上 × 可单删；选择自动保存到 localStorage 按表记忆，选完即自动重查',\n  storagePrefix:'api_test_src_cols',\n  /* 选完立即体现：所选列都在已查回的数据里 → 本地按所选列重渲染（零请求）；\n     数据里没有的列 / 清空但当前数据只是全列子集 → 才实查 */\n  onChange:(vals)=>{\n    if(!srcCurTable || !srcLastData || !srcLastData.rows.length) {\n      if(srcCurTable){ clearTimeout(srcColsAutoTimer); srcColsAutoTimer=setTimeout(()=>srcQuery(srcCurTable),150); }\n      return;\n    }\n    const have=new Set(Object.keys(srcLastData.rows[0]).map(c=>c.toLowerCase()));\n    const localOk = vals.length\n      ? vals.every(v=>have.has(String(v).toLowerCase()))\n      : have.size >= ((SRC_COLS[colBase(srcCurTable)]||new Set()).size || have.size);\n    clearTimeout(srcColsAutoTimer);\n    if(localOk){\n      srcColsAutoTimer=setTimeout(()=>{\n        renderSrcData(srcLastData, 0, {...srcLastOpt, showCols:vals.length?vals:undefined, cols:vals.join(',')});\n      },120);\n    } else {\n      srcColsAutoTimer=setTimeout(()=>srcQuery(srcCurTable),150);\n    }\n  },\n});\n\nfunction renderSrcData(d, ms, opt){\n  const box=$('#srcResult');\n  const cols=opt.cols;\n  const extra=(opt.flts.length?'<span class=\"badge src\">过滤 '+opt.flts.map(f=>esc(f.split('|').join(' '))).join(' AND ')+'</span>':'')\n    +(cols?'<span class=\"badge land\">仅 '+cols.split(',').length+' 列</span>':'')\n    +($('#srcLimit').value==='0'?'<span class=\"badge land\">不限行数</span>':'')\n    +(opt.fromCache?'<span class=\"badge time\">🕘 来自浏览器缓存</span>':'');\n  let html='<div class=\"srcmeta\">'\n    +'<span class=\"badge mod\">📁 模块：'+esc(d.module)+'</span>'\n    +(d.is_source?'<span class=\"badge src\">源表 → 自动改查落地表</span>':'<span class=\"badge land\">落地表 · 直查</span>')\n    +extra\n    +'<span class=\"badge time\">⏱ '+(opt.fromCache?'—':ms+' ms')+' · '+d.rows.length+' 行</span></div>';\n  if(opt.fromCache && opt.key){\n    const tm=opt.t?(Date.now()-opt.t<60000?'刚刚':new Date(opt.t).toLocaleString()):'';\n    const btn='<button class=\"cache-re\" type=\"button\" data-re=\"'+esc(opt.name)+'\">↻ 重新查询</button>';\n    html+='<div class=\"hint\" style=\"margin:0 0 8px\"><span class=\"cache-badge\">🕘 缓存 '+esc(tm)+'</span> '+btn+'</div>';\n  }\n  html+='<div class=\"mapline\"><b>源表</b> '+(d.source_tables.length?d.source_tables.map(t=>'<code>'+esc(t)+'</code>').join(' '):'<i>无</i>')\n    +'<span class=\"arw\">→</span><b>业务库落地表</b> '+d.landing_tables.map(t=>'<code>'+esc(t)+'</code>').join(' ')+'</div>';\n  if(d.landing_tables.length>1) html+=landSwitcherHTML(d.landing_tables, d.resolved_table);\n  if(d.remark) html+='<div class=\"hint\" style=\"margin:0 0 8px\">备注：'+esc(d.remark)+'</div>';\n  if(!d.rows.length){\n    html+='<div class=\"hint\">查询成功但无数据（表为空或暂无数据）</div>';\n  }else{\n    const allCols=Object.keys(d.rows[0]);\n    const sShow=opt.showCols?new Set(opt.showCols.map(x=>String(x).toLowerCase())):null;\n    const cols=sShow?allCols.filter(c=>sShow.has(c.toLowerCase())):allCols;  // showCols：本地按所选列重渲染（不发请求）\n    html+='<div class=\"dtable-wrap\"><table class=\"dtable\"><thead><tr>'\n      +cols.map(c=>'<th title=\"'+esc(c)+'\">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'\n      +d.rows.map(r=>'<tr>'+cols.map(c=>'<td title=\"'+esc(r[c]==null?'':String(r[c]))+'\">'+esc(r[c]==null?'∅':String(r[c]))+'</td>').join('')+'</tr>').join('')\n      +'</tbody></table></div>';\n  }\n  box.innerHTML=html;\n  const rb=box.querySelector('[data-re]');\n  if(rb) rb.onclick=()=>srcQuery(rb.dataset.re,{force:true});   // force：手动重查必走实时（参数可能已被用户改过，旧缓存键对不上）\n  bindLandSwitcher(d.landing_tables, d.resolved_table);\n}\n\nlet srcLastInput='', srcCurTable=null;   // 输入框上次查询的表 / 当前落地表选择（切表后点「查询」不重置）\nlet srcLastKey='';                        // 上次查询的完整 URL：与本次一致才允许用缓存（改了列/过滤 → 实时查）\nasync function srcQuery(nameOverride, opts){\n  const force=!!(opts&&opts.force);\n  const name=(nameOverride||srcCb.value()).trim();\n  const box=$('#srcResult');\n  const warn=$('#srcFltWarn');\n  if(!name){ box.innerHTML=''; warn.hidden=true; return; }\n  // 记录「输入框查过哪张表」：输入未变时点「查询」复用当前落地表选择，不重置\n  if(!nameOverride) srcLastInput=name;\n\n  // ② 组装请求（只带目标表存在的列；先校验再拼 URL，缓存键与真实请求一致）\n  const colSet=await resolveCols(name);\n  // 目标表有记忆的列选择 → 先恢复（保证刷新后第一次查询即按记忆列生效）\n  if(colSet){\n    const tb=await resolveTargetBase(name);\n    if(tb) srcColsCbx.setOptions([...colSet].sort().map(c=>({value:c})), tb);\n  }\n  const disabledFlts=[], disabledCols=[];\n  document.querySelectorAll('#srcFltWrap .fltr').forEach(d=>{\n    const c=d.querySelector('.fcolbox input').value.trim(), v=d.querySelector('.fval').value.trim();\n    const bad=!!colSet && c && v!=='' && !colSet.has(c.toLowerCase());\n    d.classList.toggle('off',bad);\n    d.querySelector('.fcolbox input').classList.toggle('bad',bad);\n    if(bad) disabledFlts.push(c);\n  });\n  if(!colSet) document.querySelectorAll('#srcFltWrap .fltr.off').forEach(d=>d.classList.remove('off'));\n  const p=new URLSearchParams();\n  p.set('name',name);\n  p.set('limit',$('#srcLimit').value||'0');\n  const flts=[];\n  document.querySelectorAll('#srcFltWrap .fltr').forEach(d=>{\n    const c=d.querySelector('.fcolbox input').value.trim(), o=d.querySelector('.fop').value, v=d.querySelector('.fval').value.trim();\n    if(!c || v==='') return;\n    if(colSet && !colSet.has(c.toLowerCase())) return;  // 目标表没有的列不下发\n    const s=c+'|'+o+'|'+v; flts.push(s); p.append('flt',s);\n  });\n  let cols=srcColsCbx.value().trim();\n  if(cols && colSet){\n    const keep=[];\n    cols.split(',').map(s=>s.trim()).filter(Boolean).forEach(c=>{\n      (colSet.has(c.toLowerCase())?keep:disabledCols).push(c);\n    });\n    if(keep.length) p.set('cols',keep.join(','));\n  } else if(cols) p.set('cols',cols);\n  const url=base()+'/data/table-map/data?'+p.toString();\n\n  if(disabledFlts.length || disabledCols.length){\n    warn.innerHTML='⚠️ 目标表 <b>'+esc(name)+'</b> 没有这些列，本次已自动禁用（不下发）：'\n      +(disabledFlts.length?'过滤条件 <b>'+esc(disabledFlts.join(', '))+'</b>':'')\n      +(disabledFlts.length&&disabledCols.length?'、':'')\n      +(disabledCols.length?'显示列 <b>'+esc(disabledCols.join(', '))+'</b>':'')\n      +'。对应条件行已置灰，可修改列名或删除该条件。';\n    warn.hidden=false;\n  } else warn.hidden=true;\n\n  // ③ 浏览器缓存命中 → 直接恢复，不重复请求（「↻ 重新查询」可强制刷新）\n  const ck=cacheKeyOf('GET', url);\n  const ent=(force||ck!==srcLastKey)?null:cacheGet(ck);\n  if(ent && ent.r && ent.r.code===0){\n    renderSrcData(ent.r.data, 0, {fromCache:true, t:ent.t, flts:ent.r.data.flts||[], cols:cols, key:ck, name});\n    srcCurTable=ent.r.data.resolved_table;\n    bumpSrcQueryStat(ent.r.data.resolved_table);\n    srcLastKey=ck;\n    srcLastData=ent.r.data;\n    srcLastOpt={fromCache:true, t:ent.t, flts:ent.r.data.flts||[], cols:cols, key:ck, name};\n    refreshSrcColOptions(ent.r.data.resolved_table);\n    return;\n  }\n\n  // ④ 实查\n  box.innerHTML='<div class=\"hint\">查询中…</div>';\n  const t0=performance.now();\n  try{\n    const r=await fetch(url);\n    const j=await r.json();\n    const ms=Math.round(performance.now()-t0);\n    if(j.code!==0){ box.innerHTML='<div class=\"err-box\">'+esc(j.message)+'</div>'; return; }\n    const d=j.data;\n    cacheSave(ck, j, null);\n    renderSrcData(d, ms, {fromCache:false, flts:flts, cols:cols, name});\n    srcCurTable=d.resolved_table;\n    bumpSrcQueryStat(d.resolved_table);\n    srcLastKey=ck;\n    srcLastData=d;\n    srcLastOpt={fromCache:false, flts:flts, cols:cols, name};\n    refreshSrcColOptions(d.resolved_table);\n  }catch(e){\n    box.innerHTML='<div class=\"err-box\">请求失败：'+esc(e.message)+'</div>';\n  }\n}\n$('#srcBtn').onclick=function(){\n  // 输入框表名没变 → 复用当前落地表选择重查（过滤/列保留），不重置切换器\n  if(srcCurTable && srcLastInput && (srcCb.value()||'').trim()===srcLastInput) srcQuery(srcCurTable);\n  else srcQuery();\n};\n\n/* 落地表切换器：查询成功后渲染，选中/输入其他落地表 → 保留过滤条件与列重查（不存在的列自动禁用） */\nfunction landSwitcherHTML(tables, cur){\n  return '<div class=\"land-switcher\">'\n    +'<span class=\"lbl\">🗂️ 本模块其他落地表（切换即重查；过滤列自动按新表校验，新表没有的条件会置灰禁用）</span>'\n    +'<div class=\"cbx\" id=\"landCb\"></div></div>';\n}\nfunction bindLandSwitcher(tables, cur){\n  const box=$('#landCb'); if(!box || !tables || !tables.length) return;\n  const curTable=cur||tables[0];\n  const cb=makeCombobox(box,{\n    placeholder:curTable,\n    title:'输入关键字搜索，或直接输入落地表名回车',\n    options:tables.map(t=>({\n      value:t,\n      desc:(t===curTable?'当前':'业务库落地表'),\n      tags:tableTags(ALL_TBL_MAP[colBase(t)]),\n      dim:!!(ALL_TBL_MAP[colBase(t)]||{}).empty,\n    })),\n    onEnter:()=>{ const v=cb.value(); if(v && v!==curTable) srcQuery(v); },\n    onChange:v=>{ if(v!==curTable) srcQuery(v); },\n  });\n  cb.set(curTable);\n}\n\n/* ================= 全表盘点（audit） ================= */\nlet AUDIT_TABLES=[], AUDIT_RESULTS={}, AUDIT_STOP=false, AUDIT_RUNNING=false;\n\nfunction auditTypeTags(t){\n  const tags=[];\n  if(t.is_source) tags.push('<span class=\"badge src\">源表</span>');\n  if(t.is_landing) tags.push('<span class=\"badge land\">落地表</span>');\n  if(t.biz) tags.push('<span class=\"badge biz\">biz</span>');\n  if(t.is_app) tags.push('<span class=\"badge mod\">应用表</span>');\n  return tags.join(' ');\n}\nfunction auditKindScore(t){  // 勾选过滤用：高到低 源/落/biz/元素\n  return (t.is_source?8:0)+(t.is_landing?4:0)+(t.biz?2:0)+(t.is_app?16:0)+(t.originals.length>0&&!t.is_source&&!t.is_landing&&!t.biz&&!t.is_app?1:0);\n}\nfunction auditFiltered(){\n  const kw=($('#auditKw').value||'').trim().toLowerCase();\n  const fSrc=$('#auditFltSrc').checked, fLand=$('#auditFltLand').checked, fBiz=$('#auditFltBiz').checked, fElem=$('#auditFltElem').checked;\n  return AUDIT_TABLES.filter(t=>{\n    if(kw && !t.base.includes(kw) && !(t.originals||[]).join(' ').toLowerCase().includes(kw)) return false;\n    if(t.is_app) return true; // 应用表（月报存储，应用 schema）恒显示\n    const isElemOnly=t.originals.length>0 && !t.is_source && !t.is_landing && !t.biz;\n    if(t.is_source && !fSrc) return false;\n    if(t.is_landing && !fLand) return false;\n    if(t.biz && !fBiz) return false;\n    if(isElemOnly && !fElem) return false;\n    return true;\n  });\n}\nfunction auditTableRow(t){\n  const res=AUDIT_RESULTS[t.base];\n  const st = res ? (res.meta&&res.meta.exists?'<span class=\"badge land\" title=\"业务库中存在\">✅</span>'\n          : res.is_source && res.module ? '<span class=\"badge src\" title=\"源表位于上游库\">☁️</span>'\n          : '<span class=\"badge src\" title=\"业务库未找到\">❌</span>') : '';\n  const metaTxt = res && res.meta && res.meta.exists\n    ? (res.meta.estimated_rows==null?'': '约 '+res.meta.estimated_rows+' 行 · ') + (res.meta.column_count==null?'':res.meta.column_count+' 列')\n    : '';\n  return '<div class=\"audit-row\" data-base=\"'+esc(t.base)+'\"><div class=\"srcbar\" style=\"margin:2px 0\">'\n    + st + ' <code style=\"flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis\" title=\"'+esc(t.base)+'\">'+esc(t.base)+'</code>'\n    + ' ' + auditTypeTags(t)\n    + '<span class=\"hint\" style=\"margin:0 8px 0 0\">'+(t.is_app?'应用schema(月报存储)':t.modules&&t.modules.length?esc(t.modules.join('/')):(t.biz?esc((t.biz.module||t.biz.sub_module||'biz')):'元素'))+'</span>'\n    + '<span class=\"hint\" style=\"margin:0 6px 0 0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">'+esc(metaTxt)+'</span>'\n    + '<button class=\"btn btn-ghost\" data-act=\"inspect\">'+(res?'重新体检':'🔎 体检')+'</button></div>'\n    + (res ? '<div class=\"audit-detail\">'+auditResultHTML(t,res)+'</div>' : '')\n    + '</div>';\n}\nfunction auditResultHTML(t,res){\n  let h='<div class=\"audit-detail-inner\">';\n  if(res.note) h+='<div class=\"err-box\">'+esc(res.note)+'</div>';\n  if(res.match_check) h+='<div class=\"err-box\">'+esc(res.match_check)+'</div>';\n  if(res.elements && res.elements.length){\n    h+='<div class=\"hint\" style=\"margin:2px 0\">🎯 数据元素绑定：'+res.elements.map(e=>esc(`[${e.id}] ${e.element_key||''} ${e.name||''} (${e.data_kind||''})`)).join('；')+'</div>';\n  }\n  if(res.meta && res.meta.exists){\n    h+='<div class=\"srcmeta\"><span class=\"badge land\" title=\"表注释(中文备注)\">📝 '+esc(res.meta.table_comment||'（无注释）')+'</span>'\n      +'<span class=\"badge src\" title=\"information_schema 估算值\">行数≈'+esc(String(res.meta.estimated_rows))+'</span>'\n      +'<span class=\"badge mod\">'+esc(String(res.meta.column_count))+' 列</span></div>';\n  }\n  if(res.module){\n    h+='<div class=\"mapline\"><b>模块</b> <code>'+esc(res.module)+'</code>'\n      +' <b>源表</b> '+(res.source_tables&&res.source_tables.length?res.source_tables.map(x=>'<code>'+esc(x)+'</code>').join(' '):'<i>无</i>')\n      +'<span class=\"arw\">→</span><b>落地表</b> '+(res.landing_tables&&res.landing_tables.length?res.landing_tables.map(x=>'<code>'+esc(x)+'</code>').join(' '):'<i>无</i>')+'</div>';\n  }\n  if(res.biz){\n    h+='<div class=\"hint\" style=\"margin:2px 0\">📄 business_tables.json：' + esc([res.biz.module,res.biz.sub_module,res.biz.table_type].filter(Boolean).join(' / '))+'</div>';\n  }\n  if(res.sample && res.sample.rows && res.sample.rows.length){\n    h+='<div class=\"hint\" style=\"margin:6px 0 2px\">前 '+res.sample.returned+' 行样例：</div>'\n      +'<div class=\"dtable-wrap\"><table class=\"dtable\"><thead><tr>'+res.sample.columns.map(c=>'<th title=\"'+esc(c)+'\">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'\n      +res.sample.rows.map(r=>'<tr>'+res.sample.columns.map(c=>'<td title=\"'+esc(r[c]==null?'':String(r[c]))+'\">'+esc(r[c]==null?'∅':String(r[c]))+'</td>').join('')+'</tr>').join('')\n      +'</tbody></table></div>';\n  } else if(res.sample && res.meta && res.meta.exists){\n    h+='<div class=\"hint\">查询成功但无数据（表为空或暂无数据）</div>';\n  }\n  h+='</div>';\n  return h;\n}\nfunction auditRender(){\n  const list=auditFiltered();\n  $('#auditList').innerHTML = list.length\n    ? '<div class=\"hint\" style=\"margin:4px 0\">共 '+list.length+' 张表（过滤后）</div>' + list.map(auditTableRow).join('')\n    : '<div class=\"hint\">无匹配表</div>';\n}\nfunction auditProgress(){\n  const done=Object.keys(AUDIT_RESULTS).length, total=AUDIT_TABLES.length;\n  const allOk=Object.values(AUDIT_RESULTS).filter(r=>r.meta&&r.meta.exists).length;\n  const srcOnly=Object.values(AUDIT_RESULTS).filter(r=>r.is_source&&!r.meta).length;\n  const miss=Object.values(AUDIT_RESULTS).filter(r=>!r.is_source&&!r.meta).length;\n  $('#auditProgress').innerHTML='✅ '+done+'/'+total+' 已体检 · 业务库存在 '+allOk+' · 上游源表(不可直查) '+srcOnly+' · 未找到 '+miss;\n}\nasync function auditLoad(){\n  try{\n    const r=await fetch(base()+'/data/table-map/tables');\n    const j=await r.json();\n    if(j.code!==0){ $('#auditSummary').textContent='加载清单失败：'+j.message; return; }\n    AUDIT_TABLES=j.data.tables;\n    $('#auditSummary').innerHTML='共 <b>'+j.data.total+'</b> 张表（源表 '+j.data.source_count+' · 落地表 '+j.data.landing_count+' · 应用表 '+(j.data.app_count||0)+'）· 点击「🔎 体检」逐表查，或「全部检查」批量跑（并发 3，每张约 2-4s）';\n    auditRender();\n  }catch(e){\n    $('#auditSummary').textContent='加载清单失败：'+e.message;\n  }\n}\nasync function auditInspect(baseName){\n  const params=new URLSearchParams({name:baseName, rows:'20'});\n  try{\n    const r=await fetch(base()+'/data/table-map/inspect?'+params.toString());\n    const j=await r.json();\n    AUDIT_RESULTS[baseName]=j.code===0 ? j.data : {note:'接口错误：'+(j.message||'')};\n  }catch(e){\n    AUDIT_RESULTS[baseName]={note:'请求失败：'+e.message};\n  }\n  auditProgress();\n  auditRender();\n}\nasync function auditRunAll(){\n  if(AUDIT_RUNNING){ return; }\n  AUDIT_RUNNING=true; AUDIT_STOP=false;\n  $('#auditRunAll').disabled=true; $('#auditStop').disabled=false;\n  const tasks=auditFiltered();\n  let idx=0;\n  const worker=async()=>{\n    while(idx<tasks.length && !AUDIT_STOP){\n      const t=tasks[idx++];\n      await auditInspect(t.base);\n    }\n  };\n  const workers=[worker(),worker(),worker()];\n  await Promise.all(workers);\n  AUDIT_RUNNING=false;\n  $('#auditRunAll').disabled=false; $('#auditStop').disabled=true;\n  if(AUDIT_STOP) $('#auditProgress').innerHTML+= ' · <b>已停止</b>';\n}\nfunction auditBind(){\n  $('#auditRunAll').onclick=auditRunAll;\n  $('#auditStop').onclick=()=>{ AUDIT_STOP=true; };\n  $('#auditKw').addEventListener('keydown',e=>{ if(e.key==='Enter') auditRender(); });\n  $('#auditFltSrc').onchange=$('#auditFltLand').onchange=$('#auditFltBiz').onchange=$('#auditFltElem').onchange=auditRender;\n  $('#auditList').addEventListener('click',async e=>{\n    const btn=e.target.closest('button[data-act=\"inspect\"]');\n    if(!btn) return;\n    const row=e.target.closest('.audit-row'); if(!row) return;\n    const baseName=row.dataset.base;\n    btn.disabled=true; btn.textContent='查询中…';\n    await auditInspect(baseName);\n  });\n}\nfunction loadAudit(){\n  $('#auditList').innerHTML='';\n  $('#auditProgress').textContent='';\n  $('#auditSummary').textContent='加载中…';\n  AUDIT_RESULTS={};\n  auditBind();\n  auditLoad();\n}\n\n/* 源表 combobox（可搜索，未加载完成前也可自由输入） */\nconst srcCb=makeCombobox($('#srcCb'),{\n  placeholder:'输入关键字搜索表名/中文备注，或直接输入表名',\n  title:'业务库 netcare 全量 441 张表（有数据的靠前，空表置灰靠后）；彩色标签 = 模块 / 类别',\n  onEnter:()=>srcQuery(),\n});\n\n/* 全表目录（all_tables.json 内置）：表名 -> {cn, mod, cate, rows, empty} */\nlet ALL_TBL_MAP={};\n/* 类别 -> 彩色标签 class（与 CSS .ctag.tg-* 对应） */\nconst CATE_CLS={'公共基础表（维表/关联关系）':'tg-pub','重大事件':'tg-maj','风险':'tg-risk','整改':'tg-rect','License':'tg-lie','账务':'tg-acct','维护/检修':'tg-maint','事件/通知/调查':'tg-inc','服务请求(问题单)':'tg-sr','任务/工单':'tg-task','网络':'tg-net','大T':'tg-pub','地区部/代表处':'tg-pub','国家地区':'tg-pub','客户':'tg-pub','产品':'tg-pub','变更':'tg-chg','IOC运营':'tg-ioc','交付':'tg-dlv','衍生':'tg-derv','其他':'tg-oth'};\nfunction tableTags(e){\n  if(!e) return '';\n  let h='';\n  if(e.mod) h+='<span class=\"ctag tm\">'+esc(e.mod)+'</span>';\n  h+='<span class=\"ctag '+(CATE_CLS[e.cate]||'tg-oth')+'\">'+esc(e.cate)+'</span>';\n  if(e.empty) h+='<span class=\"ctag te\">空表</span>';\n  return h;\n}\n\n/* ---- 源表查询频次统计（localStorage api_test_src_query_stats = {表名: {count, last}}） ----\n   用于\"最近经常查的表优先展示\"：loadSrcList 按 count 降序 → last 降序取 Top 30 置顶。 */\nconst SRC_QUERY_STATS_KEY='api_test_src_query_stats';\nlet srcStatsLastBump={tbl:null, ts:0};\nfunction loadSrcQueryStats(){ try{ const o=JSON.parse(localStorage.getItem(SRC_QUERY_STATS_KEY)||'{}'); return o&&typeof o==='object'?o:{}; }catch(e){ return {}; } }\nfunction saveSrcQueryStats(o){ try{ localStorage.setItem(SRC_QUERY_STATS_KEY, JSON.stringify(o)); }catch(e){} }\nfunction bumpSrcQueryStat(tbl){\n  const b=colBase(tbl); if(!b) return;\n  const now=Date.now();\n  if(srcStatsLastBump.tbl===b && now-srcStatsLastBump.ts<2000) return;   // 2 秒内同表去抖\n  srcStatsLastBump={tbl:b, ts:now};\n  const o=loadSrcQueryStats();\n  const e=o[b]||(o[b]={count:0, last:0});\n  e.count=(e.count||0)+1; e.last=now;\n  saveSrcQueryStats(o);\n}\n\n/* 表下拉清单：内置业务库全量 441 表（目录顺序：有数据靠前 → 空表置灰靠后）；\n   索引目录源表名作为搜索别名命中对应落地表；中文备注参与搜索；\n   最近经常查的表（按查询频次）优先置顶展示。 */\nasync function loadSrcList(){\n  try{\n    const r1=await fetch(base()+'/data/table-map');\n    const j1=await r1.json();\n    const map={};   // 落地表 -> {mods:Set, sources:Set}\n    if(j1.code===0){\n      j1.data.modules.forEach(m=>{\n        m.landing_tables.forEach(t=>{\n          const e=map[t]||(map[t]={mods:new Set(),sources:new Set()});\n          e.mods.add(m.name);\n          m.source_tables.forEach(s=>e.sources.add(s));\n        });\n      });\n    }\n    const r2=await fetch(base()+'/data/table-map/all-tables');\n    const j2=await r2.json();\n    if(j2.code!==0 || !Array.isArray(j2.data.tables)) return;\n    j2.data.tables.forEach(e=>{ ALL_TBL_MAP[e.t]=e; });\n    /* 表快查 ID：大分类（cate）一个字母（按 CATE_CLS 顺序 A/B/C…），类内编号 001 递增；\n       显示在下拉名字开头，且可直接输入 ID 搜索（大小写均可）。\n       ID 按原始目录顺序生成（稳定，不因频次排序而变）。 */\n    const CATE_LTRS={}; Object.keys(CATE_CLS).forEach((k,i)=>{ CATE_LTRS[k]=String.fromCharCode(65+i); });\n    const idCnt={}, idOf={};\n    j2.data.tables.forEach(e=>{\n      const L=CATE_LTRS[e.cate]||'Z';\n      idCnt[L]=(idCnt[L]||0)+1;\n      idOf[e.t]=L+String(idCnt[L]).padStart(3,'0');\n    });\n    window.SRC_TBL_ID=idOf;\n    /* 最近经常查的表优先展示：按 count 降序 → last 降序取 Top 30 置顶，其余按原顺序（有数据靠前、空表靠后） */\n    const stats=loadSrcQueryStats();\n    const allTables=j2.data.tables;\n    const hot=allTables.filter(e=>stats[e.t]&&stats[e.t].count>0)\n      .sort((a,b)=>(stats[b.t].count-stats[a.t].count)||(stats[b.t].last-stats[a.t].last))\n      .slice(0,30);\n    const hotSet=new Set(hot.map(e=>e.t));\n    const ordered=[...hot, ...allTables.filter(e=>!hotSet.has(e.t))];\n    srcCb.setOptions(ordered.map(e=>{\n      const id=idOf[e.t], extra=map[e.t], st=stats[e.t];\n      const hotTag=(st&&st.count>=3)?'<span class=\"ctag tg-hot\" title=\"最近经常查询 · '+st.count+' 次\">🔥'+st.count+'</span>':'';\n      return {\n        value:e.t,\n        label:id+' '+e.t+(e.cn?' — '+e.cn:'')+(e.empty?'（空表）':''),\n        desc:e.cn||'',\n        tags:'<span class=\"tid\">'+id+'</span>'+hotTag+tableTags(e),\n        dim:!!e.empty,\n        kw:[id,id.toLowerCase(),extra?[...extra.sources].join(' '):'',e.mod||'',e.cate||''].filter(Boolean).join(' '),\n      };\n    }));\n  }catch(e){ /* 下拉只是增强，失败不影响手动输入 */ }\n}\nloadSrcList();\n\n/* ================= 左侧菜单搜索 ================= */\n$('#menuSearch').addEventListener('input', e=>{\n  menuSearchKw = e.target.value.trim().toLowerCase();\n  renderLeft();\n});\n\n/* ================= 左侧菜单：右缘拖拽调宽 + 拖窄自动收起为图标栏（持久化） + 分组一键全部展开/折叠 ================= */\n(function(){\n  const left=document.querySelector('.left'), rz=$('#leftRz'), rail=$('#leftRail');\n  const RAIL=56, TH=100, MAX=Math.round(window.innerWidth*0.45);\n  let w=316;\n  try{ const sw=parseInt(localStorage.getItem('api_test_left_w'),10); if(sw>=RAIL) w=sw; }catch(e){}\n  function setW(ww){\n    ww=Math.max(RAIL,Math.min(MAX,Math.round(ww)));\n    if(ww<TH) ww=RAIL;                     // 窄于阈值 → 吸附为图标栏\n    w=ww;\n    left.style.width=ww+'px';\n    left.style.flex='0 0 '+ww+'px';\n    left.classList.toggle('rail',ww<=RAIL);\n    try{ localStorage.setItem('api_test_left_w',String(ww)); }catch(e){}\n  }\n  rz.addEventListener('mousedown',e=>{\n    e.preventDefault();\n    const startX=e.clientX, startW=left.offsetWidth;\n    document.body.classList.add('left-dragging'); rz.classList.add('drag');\n    function mv(ev){ setW(startW+(ev.clientX-startX)); }\n    function up(){\n      document.removeEventListener('mousemove',mv);\n      document.removeEventListener('mouseup',up);\n      document.body.classList.remove('left-dragging'); rz.classList.remove('drag');\n    }\n    document.addEventListener('mousemove',mv);\n    document.addEventListener('mouseup',up);\n  });\n  /* 图标栏：每个大分类一个图标，点击展开侧栏并定位到该分组 */\n  function renderRail(){\n    rail.innerHTML='';\n    GROUPS.forEach((g,gi)=>{\n      if(g.key==='custom' && !g.eps.length){\n        // 空的自定义分组也在图标栏显示，点击展开侧栏\n        const b=document.createElement('button');\n        b.type='button'; b.className='rail-it'; b.dataset.g=gi;\n        b.title=g.name+'（0 项）';\n        b.innerHTML='<span>'+g.icon+'</span>';\n        b.onclick=()=>{ if(w<=RAIL) setW(280); const grp=document.querySelector('#leftPanel .grp[data-g=\"'+gi+'\"]'); if(grp){ grp.classList.remove('closed'); grp.scrollIntoView({block:'nearest',behavior:'smooth'}); } };\n        rail.appendChild(b);\n        const sep=document.createElement('div'); sep.className='rail-sep';\n        rail.appendChild(sep);\n        return;\n      }\n      const b=document.createElement('button');\n      b.type='button'; b.className='rail-it'; b.dataset.g=gi;\n      b.title=g.name+'（'+g.eps.length+' 项）';\n      b.innerHTML='<span>'+g.icon+'</span>';\n      b.onclick=()=>{\n        if(w<=RAIL) setW(280);\n        document.querySelectorAll('.rail-it').forEach(x=>x.classList.toggle('active',x===b));\n        const grp=document.querySelector('#leftPanel .grp[data-g=\"'+gi+'\"]');\n        if(grp){ grp.classList.remove('closed'); grp.scrollIntoView({block:'nearest',behavior:'smooth'}); }\n      };\n      rail.appendChild(b);\n      const sep=document.createElement('div'); sep.className='rail-sep';\n      rail.appendChild(sep);\n    });\n    const last=rail.querySelector('.rail-sep'); if(last) last.remove();\n  }\n  window.__syncLeftRail=()=>{ if(left.classList.contains('rail')) renderRail(); };\n  $('#grpExpandAll').onclick=()=>document.querySelectorAll('#leftPanel .grp').forEach(g=>g.classList.remove('closed'));\n  $('#grpCollapseAll').onclick=()=>document.querySelectorAll('#leftPanel .grp').forEach(g=>g.classList.add('closed'));\n  renderCustomGroup();   // 保证 ⭐自定义查询 分组在图标栏首帧就有数据\n  renderRail();\n  setW(w);\n})();\n\n\n/* ================= 初始化 ================= */\nfillIcons();\nrenderCustomGroup();\nrenderLeft();\ncheckHealth();\n// 默认全部分组展开（展开更美观），并选中「源表直查」（主用入口）\nsetTimeout(()=>{\n  for(let gi=0; gi<GROUPS.length; gi++){\n    const ei=GROUPS[gi].eps.findIndex(e=>e.kind==='src');\n    if(ei<0) continue;\n    let count=0; GROUPS.forEach((g,i)=>{ if(i<gi) count+=g.eps.length; });\n    const el=document.querySelectorAll('.ep')[count+ei];\n    if(el) el.click();\n    break;\n  }\n},50);\n</script>\n</body>\n</html>\n";
})();
